input.content:
:root {
  --bg: #071014;
  --bg-2: #0b1a20;
  --panel: rgba(8, 20, 25, 0.92);
  --panel-solid: #0a171c;
  --panel-light: rgba(19, 38, 44, 0.74);
  --line: rgba(168, 201, 199, 0.14);
  --line-strong: rgba(231, 197, 119, 0.3);
  --gold: #e7c577;
  --gold-2: #b58b4a;
  --cream: #f1e8d6;
  --muted: #8fa4a7;
  --dim: #5e7479;
  --teal: #72d6b8;
  --coral: #e26857;
  --danger: #d75e4f;
  --shadow: 0 26px 70px rgba(0, 0, 0, 0.55);
  --mono: "Courier New", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --display: "Arial Narrow", "Trebuchet MS", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--cream);
  font-family: var(--mono);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

button {
  font-family: var(--mono);
  color: inherit;
  cursor: pointer;
  border: 0;
  background: none;
  padding: 0;
}
button:focus-visible { outline: 2px solid var(--teal); outline-offset: 2px; }

.game-shell {
  position: relative;
  width: 100vw;
  height: 100dvh;
  min-height: 480px;
  overflow: hidden;
  background: var(--bg);
  touch-action: manipulation;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: pointer;
  touch-action: manipulation;
}

.vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 34%, rgba(0, 0, 0, 0.36) 100%),
    linear-gradient(180deg, rgba(2, 8, 10, 0.42) 0%, transparent 14%, transparent 82%, rgba(2, 6, 8, 0.5) 100%);
  z-index: 4;
}
.grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.18;
  z-index: 4;
  background-image: repeating-linear-gradient(0deg, rgba(255,255,255,.045) 0, rgba(255,255,255,.045) 1px, transparent 1px, transparent 3px);
  mix-blend-mode: soft-light;
}

/* ------------------------------------------------------------------ topbar */
.topbar {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 20px 18px;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(3, 9, 11, 0.9) 0%, rgba(3, 9, 11, 0.55) 62%, transparent 100%);
}
.topbar > * { pointer-events: auto; }

.brand { display: flex; align-items: center; gap: 10px; min-width: 220px; }
.brand-mark {
  width: 42px; height: 42px;
  display: grid; place-items: center;
  background: linear-gradient(145deg, #142a2e, #091216);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.07), 0 4px 16px rgba(0,0,0,.4);
}
.brand-mark svg { width: 30px; height: 22px; filter: drop-shadow(0 0 5px rgba(231,197,119,.25)); }
.brand-text h1 {
  margin: 0;
  font-family: var(--display);
  font-size: 21px;
  line-height: 1;
  letter-spacing: 3.5px;
  font-weight: 900;
  color: var(--cream);
  text-shadow: 0 2px 14px rgba(0,0,0,.6);
}
.brand-text span {
  display: block;
  margin-top: 5px;
  font-size: 7.5px;
  letter-spacing: 1.7px;
  color: var(--muted);
  white-space: nowrap;
}
.brand-text span i { color: var(--gold-2); font-style: normal; }

.day-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border: 1px solid var(--line);
  background: rgba(8, 19, 23, .78);
  border-radius: 7px;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
  font-size: 9px;
  letter-spacing: 1px;
  color: var(--muted);
  white-space: nowrap;
}
.day-chip .day-label { font-size: 7px; color: var(--dim); letter-spacing: 1.5px; }
.day-chip strong { color: var(--cream); font-size: 12px; }
.day-chip .day-div { width: 1px; height: 13px; background: var(--line); }
.day-chip .clock { color: var(--gold); font-weight: 700; font-size: 11px; letter-spacing: 1.5px; }

.top-actions { display: flex; align-items: center; gap: 8px; }
.icon-btn {
  width: 34px; height: 34px;
  display: grid; place-items: center;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: rgba(8, 19, 23, .78);
  color: var(--muted);
  font-family: var(--display);
  font-size: 17px;
  font-weight: 800;
  transition: .16s ease;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.04);
}
.icon-btn svg { width: 17px; height: 17px; }
.icon-btn:hover { color: var(--gold); border-color: var(--line-strong); background: rgba(16, 35, 39, .92); }
.icon-btn.muted .wave { opacity: .18; }

.wallet {
  position: relative;
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 152px;
  padding: 6px 14px 7px 30px;
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  background:
    linear-gradient(140deg, rgba(231,197,119,.11), transparent 44%),
    rgba(8, 20, 24, .9);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.06), 0 7px 24px rgba(0,0,0,.35);
  overflow: hidden;
  transition: .18s ease;
}
.wallet .wallet-label {
  position: absolute;
  top: 3px; left: 31px;
  font-size: 6px;
  letter-spacing: 1.5px;
  color: var(--gold-2);
}
.wallet strong {
  font-size: 16px;
  line-height: 1;
  letter-spacing: .6px;
  color: #f8efd9;
  font-variant-numeric: tabular-nums;
}
.wallet em { font-style: normal; font-size: 8px; color: var(--gold); letter-spacing: 1px; }
.wallet-coin {
  position: absolute;
  left: 9px; top: 50%;
  width: 14px; height: 14px;
  transform: translateY(-50%);
  border-radius: 50%;
  border: 1px solid #f0d28a;
  background: radial-gradient(circle at 35% 30%, #ffe9a6, #c39a43 65%, #8a6528);
  box-shadow: 0 0 8px rgba(231,197,119,.35);
}
.wallet.flash { border-color: var(--teal); box-shadow: 0 0 0 1px rgba(114,214,184,.24), 0 0 28px rgba(114,214,184,.15); }

/* ------------------------------------------------------------------- hints */
.hint {
  position: absolute;
  left: 106px;
  bottom: 114px;
  z-index: 18;
  display: flex;
  align-items: center;
  gap: 8px;
  max-width: min(560px, 60vw);
  padding: 7px 13px;
  border: 1px solid rgba(114, 214, 184, .22);
  border-radius: 6px;
  background: rgba(5, 16, 19, .8);
  color: #bfd4cd;
  font-size: 9px;
  letter-spacing: .6px;
  transition: opacity .35s, transform .35s;
  pointer-events: none;
  backdrop-filter: blur(5px);
}
.hint.hide { opacity: 0; transform: translateY(6px); }
.hint-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 9px rgba(114,214,184,.8);
}

/* --------------------------------------------------------------- food rail */
.food-rail {
  position: absolute;
  left: 14px;
  top: 92px;
  z-index: 20;
  width: 82px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.rail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px 2px;
  font-size: 7px;
  letter-spacing: 2.2px;
  color: var(--gold-2);
}
.rail-head i { width: 18px; height: 1px; background: var(--line-strong); }
.rail-items { display: flex; flex-direction: column; gap: 7px; }
.food-btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  height: 64px;
  padding: 5px 3px 4px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: linear-gradient(145deg, rgba(21, 44, 49, .84), rgba(7, 17, 21, .9));
  color: var(--muted);
  transition: .16s ease;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.045), 0 4px 10px rgba(0,0,0,.25);
}
.food-btn:hover { border-color: rgba(231,197,119,.32); transform: translateX(2px); }
.food-btn .food-icon { width: 27px; height: 27px; filter: drop-shadow(0 2px 3px rgba(0,0,0,.4)); }
.food-btn .food-name { font-size: 6.4px; letter-spacing: .6px; line-height: 1.1; text-align: center; }
.food-btn .food-count {
  position: absolute;
  top: 3px; right: 4px;
  min-width: 15px;
  padding: 1px 3px;
  border-radius: 3px;
  background: rgba(4, 12, 14, .9);
  border: 1px solid rgba(143,164,167,.22);
  color: #b7c8c6;
  font-size: 6.5px;
  font-weight: 700;
}
.food-btn.empty .food-count { color: var(--danger); border-color: rgba(215,94,79,.4); }
.food-btn.active {
  border-color: rgba(231,197,119,.8);
  background: linear-gradient(145deg, rgba(53, 58, 39, .9), rgba(22, 30, 25, .94));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.08), 0 0 0 1px rgba(231,197,119,.12), 0 0 22px rgba(231,197,119,.1);
  color: var(--cream);
  transform: translateX(3px);
}
.food-btn.active::before {
  content: "";
  position: absolute;
  left: -6px; top: 14px; bottom: 14px;
  width: 2px;
  border-radius: 2px;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(231,197,119,.6);
}
.food-btn.active .food-count { border-color: rgba(231,197,119,.45); color: var(--gold); }
.rail-foot {
  margin-top: 2px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 5px;
  border-top: 1px solid var(--line);
  font-size: 5.5px;
  color: var(--dim);
  letter-spacing: 1px;
  text-align: center;
}
.rail-foot b { color: var(--gold-2); font-size: 5.8px; letter-spacing: .6px; }

/* ------------------------------------------------------------------- toasts */
.toast-stack {
  position: absolute;
  top: 80px;
  right: 20px;
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 7px;
  width: min(310px, calc(100vw - 32px));
  pointer-events: none;
}
.toast {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold);
  border-radius: 5px;
  background: rgba(6, 17, 20, .95);
  box-shadow: 0 8px 26px rgba(0,0,0,.45);
  color: #d8e0d8;
  font-size: 9px;
  line-height: 1.45;
  letter-spacing: .25px;
  animation: toastIn .22s ease both;
  backdrop-filter: blur(6px);
}
.toast.out { animation: toastOut .25s ease both; }
.toast .toast-icon { color: var(--gold); font-size: 11px; line-height: 1; }
.toast.good { border-left-color: var(--teal); }
.toast.good .toast-icon { color: var(--teal); }
.toast.bad { border-left-color: var(--danger); }
.toast.bad .toast-icon { color: var(--danger); }
@keyframes toastIn { from { opacity: 0; transform: translateX(12px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateX(12px); } }

/* -------------------------------------------------------------------- tray */
.tray {
  position: absolute;
  left: 104px;
  right: 18px;
  bottom: 12px;
  z-index: 25;
  height: 88px;
  display: flex;
  align-items: stretch;
  gap: 10px;
  padding: 8px 9px 8px 13px;
  border: 1px solid var(--line);
  border-top: 1px solid var(--line-strong);
  border-radius: 9px;
  background:
    linear-gradient(180deg, rgba(21, 42, 46, .58), rgba(5, 14, 17, .92) 38%),
    rgba(5, 14, 17, .9);
  box-shadow: 0 -10px 40px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.045);
  backdrop-filter: blur(8px);
}
.tray::before {
  content: "";
  position: absolute;
  top: -1px; left: 8%; right: 8%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(231,197,119,.55), transparent);
}
.tray-head {
  flex: 0 0 122px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 4px;
  padding-right: 10px;
  border-right: 1px solid var(--line);
}
.tray-head .eyebrow { display: block; font-size: 6px; letter-spacing: 1.4px; color: var(--dim); }
.tray-head strong { font-family: var(--display); font-size: 13px; letter-spacing: 1.4px; color: var(--gold); }
.tray-head b { font-size: 8px; color: var(--muted); letter-spacing: 1px; }
.tray-items {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}
.tray-items::-webkit-scrollbar { display: none; }
.tray-slot {
  position: relative;
  flex: 0 0 62px;
  width: 62px;
  height: 66px;
  border: 1px dashed rgba(143,164,167,.24);
  border-radius: 5px;
  background: rgba(9, 21, 24, .5);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  transition: .15s ease;
  cursor: pointer;
  user-select: none;
}
.tray-slot.empty { cursor: default; opacity: .75; }
.tray-slot.empty::after { content: "+"; color: rgba(143,164,167,.28); font-size: 13px; }
.tray-slot:hover { border-color: rgba(231,197,119,.35); background: rgba(18, 35, 37, .65); }
.tray-slot.selected {
  border: 1px solid var(--gold);
  background: linear-gradient(145deg, rgba(79, 68, 37, .5), rgba(20, 28, 24, .75));
  box-shadow: 0 0 0 1px rgba(231,197,119,.14), 0 0 18px rgba(231,197,119,.13);
}
.tray-slot.dragging { opacity: .35; }
.tray-slot img { width: 44px; height: 35px; object-fit: contain; filter: drop-shadow(0 2px 4px rgba(0,0,0,.5)); pointer-events: none; }
.tray-slot .decor-img { width: 36px; height: 35px; }
.tray-slot .tray-name {
  max-width: 56px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 6px;
  letter-spacing: .2px;
  color: #b9c8c4;
  pointer-events: none;
}
.tray-slot .tray-tag {
  position: absolute; top: 2px; left: 3px;
  font-size: 5px; color: var(--gold-2); letter-spacing: .4px; pointer-events: none;
}
.tray-slot .tray-remove {
  position: absolute;
  top: -4px; right: -4px;
  width: 15px; height: 15px;
  border-radius: 50%;
  border: 1px solid rgba(215,94,79,.5);
  background: #131c1d;
  color: #d98a7d;
  font-size: 7px;
  display: grid; place-items: center;
  opacity: 0;
  transition: .15s;
  z-index: 2;
}
.tray-slot:hover .tray-remove, .tray-slot.selected .tray-remove { opacity: 1; }
.tray-actions { flex: 0 0 152px; display: flex; align-items: stretch; }
.shop-button {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border: 1px solid rgba(231,197,119,.5);
  border-radius: 6px;
  background:
    linear-gradient(135deg, rgba(231,197,119,.16), transparent 55%),
    #1a2a26;
  color: var(--gold);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.09), 0 4px 18px rgba(0,0,0,.25);
  transition: .16s ease;
}
.shop-button:hover { background: #24382f; border-color: var(--gold); box-shadow: 0 0 22px rgba(231,197,119,.12); }
.shop-button svg { width: 22px; height: 22px; }
.shop-button span { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; }
.shop-button b { font-family: var(--display); font-size: 13px; letter-spacing: 2px; }
.shop-button small { font-size: 5.5px; letter-spacing: .8px; color: rgba(231,197,119,.6); }

/* ------------------------------------------------------------------ modals */
.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 22px;
}
.modal-scrim {
  position: absolute;
  inset: 0;
  background: rgba(1, 5, 7, .72);
  backdrop-filter: blur(4px);
  animation: fadeIn .18s ease both;
}
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
.panel {
  position: relative;
  border: 1px solid rgba(168, 201, 199, .18);
  background:
    linear-gradient(150deg, rgba(231,197,119,.04), transparent 28%),
    linear-gradient(180deg, rgba(12, 29, 34, .98), rgba(5, 14, 17, .99));
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255,255,255,.055);
  z-index: 1;
  animation: panelIn .22s cubic-bezier(.2,.8,.25,1) both;
}
.panel::before {
  content: "";
  position: absolute;
  top: -1px; left: 12%; right: 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(231,197,119,.65), transparent);
  z-index: 2;
}
@keyframes panelIn { from { opacity: 0; transform: translateY(10px) scale(.99); } to { opacity: 1; transform: none; } }

.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 20px 14px;
  border-bottom: 1px solid var(--line);
}
.modal-head h2 {
  margin: 4px 0 0;
  font-family: var(--display);
  font-size: 23px;
  letter-spacing: 3px;
  line-height: 1;
}
.eyebrow { font-size: 7px; letter-spacing: 2px; color: var(--gold-2); text-transform: uppercase; }
.close-btn { font-size: 12px; }
.shop-wallet { display: flex; align-items: baseline; gap: 4px; padding: 6px 10px; border: 1px solid var(--line); border-radius: 5px; background: rgba(4,12,14,.5); }
.shop-wallet span { font-size: 6px; letter-spacing: 1px; color: var(--dim); margin-right: 4px; }
.shop-wallet strong { font-size: 13px; color: var(--gold); font-variant-numeric: tabular-nums; }
.shop-wallet em { font-style: normal; font-size: 7px; color: var(--gold-2); }

/* -------------------------------------------------------------------- shop */
.shop-card {
  width: min(1120px, calc(100vw - 44px));
  height: min(760px, calc(100dvh - 44px));
  border-radius: 11px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.shop-tabs { display: flex; gap: 4px; padding: 10px 20px 0; border-bottom: 1px solid var(--line); }
.shop-tabs button {
  padding: 9px 20px 10px;
  border: 1px solid transparent;
  border-bottom: 0;
  border-radius: 5px 5px 0 0;
  color: var(--dim);
  font-size: 9px;
  letter-spacing: 1.7px;
  font-weight: 700;
}
.shop-tabs button:hover { color: var(--cream); }
.shop-tabs button.active {
  color: var(--gold);
  border-color: var(--line);
  background: rgba(21, 39, 42, .6);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 -1px 0 var(--gold) inset;
}
.shop-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 20px;
  border-bottom: 1px solid rgba(168,201,199,.08);
}
.filter-pills { display: flex; gap: 5px; }
.filter-pills button {
  padding: 5px 11px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--dim);
  font-size: 7px;
  letter-spacing: 1px;
}
.filter-pills button.active { color: var(--gold); border-color: var(--line-strong); background: rgba(231,197,119,.06); }
.shop-toolbar p { margin: 0; font-size: 7.5px; color: var(--dim); letter-spacing: .3px; text-align: right; max-width: 54%; line-height: 1.5; }
.shop-grid {
  flex: 1;
  overflow-y: auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(238px, 1fr));
  gap: 10px;
  padding: 16px 20px 24px;
  align-content: start;
  scrollbar-width: thin;
  scrollbar-color: rgba(231,197,119,.25) transparent;
}
.shop-grid::-webkit-scrollbar { width: 7px; }
.shop-grid::-webkit-scrollbar-thumb { background: rgba(231,197,119,.25); border-radius: 4px; }

.shop-card-item {
  display: flex;
  flex-direction: column;
  min-height: 215px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background:
    radial-gradient(ellipse at 50% 0%, rgba(52, 130, 128, .16), transparent 62%),
    linear-gradient(180deg, rgba(19, 38, 42, .55), rgba(8, 18, 21, .7));
  overflow: hidden;
  transition: .16s ease;
}
.shop-card-item:hover { border-color: rgba(231,197,119,.28); transform: translateY(-2px); box-shadow: 0 10px 26px rgba(0,0,0,.26); }
.card-art {
  position: relative;
  height: 108px;
  display: grid;
  place-items: center;
  background:
    repeating-linear-gradient(90deg, transparent 0, transparent 24px, rgba(255,255,255,.025) 24px, rgba(255,255,255,.025) 25px),
    radial-gradient(ellipse at 50% 62%, rgba(69, 165, 160, .18), transparent 68%);
  border-bottom: 1px solid rgba(168,201,199,.08);
  overflow: hidden;
}
.card-art::after {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(6,16,19,.15), rgba(6,16,19,.55));
  pointer-events: none;
}
.card-art img { max-width: 82%; max-height: 88%; object-fit: contain; filter: drop-shadow(0 6px 12px rgba(0,0,0,.5)); z-index: 1; }
.card-art .art-badge {
  position: absolute; top: 7px; left: 8px;
  padding: 2px 5px; border: 1px solid rgba(231,197,119,.25); border-radius: 3px;
  font-size: 5.5px; letter-spacing: .8px; color: var(--gold-2);
  background: rgba(5,13,15,.65);
  z-index: 2;
}
.card-art .art-price {
  position: absolute; top: 7px; right: 8px;
  font-size: 8px; font-weight: 700; color: #f3dfaa;
  background: rgba(5,13,15,.72);
  border: 1px solid rgba(231,197,119,.2);
  border-radius: 3px; padding: 2px 5px;
  z-index: 2;
}
.card-body { padding: 9px 11px 10px; display: flex; flex-direction: column; gap: 4px; flex: 1; }
.card-body .card-name { font-family: var(--display); font-size: 13px; letter-spacing: .7px; color: var(--cream); line-height: 1.05; }
.card-body .card-vi { font-size: 7px; color: var(--gold-2); letter-spacing: .5px; }
.card-body .card-desc { font-family: var(--display); font-size: 9px; line-height: 1.35; color: var(--muted); margin: 2px 0 4px; }
.card-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: auto; }
.card-tags span { padding: 2px 5px; border: 1px solid var(--line); border-radius: 3px; font-size: 5.8px; letter-spacing: .5px; color: var(--muted); }
.card-buy {
  display: flex; align-items: center; justify-content: space-between;
  gap: 8px;
  margin-top: 7px;
  padding: 7px 9px;
  border: 1px solid rgba(231,197,119,.36);
  border-radius: 4px;
  background: rgba(231,197,119,.06);
  color: var(--gold);
  font-size: 8px;
  letter-spacing: 1px;
  font-weight: 700;
  transition: .15s;
}
.card-buy:hover { background: rgba(231,197,119,.14); border-color: var(--gold); }
.card-buy:disabled { opacity: .38; cursor: not-allowed; filter: grayscale(.4); }
.card-buy small { font-size: 6.5px; color: rgba(231,197,119,.62); letter-spacing: .4px; }
.pack-card { min-height: 180px; }
.pack-card .card-art { height: 96px; }
.pack-card .card-art .food-big { width: 66px; height: 66px; }
.stock-line { display: flex; justify-content: space-between; font-size: 6.5px; color: var(--dim); letter-spacing: .4px; margin-top: 1px; }
.stock-line b { color: var(--cream); }

/* ------------------------------------------------------------------ detail */
.detail-card {
  width: min(1280px, calc(100vw - 40px));
  height: min(850px, calc(100dvh - 40px));
  border-radius: 11px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 382px;
  overflow: hidden;
}
.detail-stage {
  position: relative;
  min-width: 0;
  min-height: 0;
  background: #050d10;
  border-right: 1px solid var(--line);
  overflow: hidden;
  touch-action: none;
}
#detailCanvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; touch-action: none; }
.detail-stage.mode-clean #detailCanvas { cursor: none; }
.stage-head {
  position: absolute;
  top: 14px; left: 16px; right: 16px;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  pointer-events: none;
}
.stage-head .eyebrow { color: var(--gold-2); font-size: 7px; }
.stage-head h2 {
  margin: 3px 0 0;
  font-family: var(--display);
  font-size: 26px;
  letter-spacing: 4px;
  line-height: 1;
  text-shadow: 0 3px 18px rgba(0,0,0,.8);
}
.stage-chips { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; }
.stage-chips span {
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 3px;
  background: rgba(4, 12, 15, .66);
  color: var(--muted);
  font-size: 6.5px;
  letter-spacing: .8px;
  backdrop-filter: blur(4px);
}
.stage-chips span:last-child { color: var(--teal); border-color: rgba(114,214,184,.25); }
.stage-chips span:last-child.off { color: var(--dim); border-color: var(--line); }

.stage-hud {
  position: absolute;
  left: 16px; right: 16px; bottom: 14px;
  z-index: 3;
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: rgba(4, 14, 17, .88);
  box-shadow: 0 8px 24px rgba(0,0,0,.4);
  backdrop-filter: blur(6px);
}
.clean-hud { display: flex; align-items: center; gap: 16px; justify-content: space-between; }
.hud-copy { display: flex; flex-direction: column; gap: 3px; }
.hud-copy b { color: var(--teal); font-size: 8px; letter-spacing: 1.2px; }
.hud-copy span { color: var(--muted); font-size: 7.5px; line-height: 1.3; }
.hud-progress { display: flex; align-items: center; gap: 8px; min-width: 190px; }
.hud-progress i {
  display: block;
  width: 100%;
  height: 6px;
  border: 1px solid rgba(114,214,184,.28);
  border-radius: 3px;
  background: linear-gradient(90deg, #3a9e80, #83e8c2) no-repeat;
  background-size: 0% 100%;
  box-shadow: 0 0 10px rgba(114,214,184,.25);
}
.hud-progress span { color: var(--teal); font-size: 8px; min-width: 30px; text-align: right; font-weight: 700; }
.inspect-hud { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.inspect-hud small { color: var(--dim); font-size: 6.5px; letter-spacing: .4px; }
.inspect-grid { display: flex; gap: 12px; flex-wrap: wrap; }
.inspect-grid span { font-size: 6px; color: var(--dim); letter-spacing: .8px; }
.inspect-grid b { display: block; margin-top: 2px; font-size: 9px; color: var(--gold); letter-spacing: .3px; }
.decor-hud { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.hud-buttons { display: flex; gap: 6px; flex-shrink: 0; }

.detail-side { background: rgba(7, 17, 21, .96); display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.side-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 14px 16px 10px;
  border-bottom: 1px solid var(--line);
}
.side-scroll { overflow-y: auto; padding: 12px 16px 24px; scrollbar-width: thin; scrollbar-color: rgba(231,197,119,.22) transparent; }
.side-scroll::-webkit-scrollbar { width: 6px; }
.side-scroll::-webkit-scrollbar-thumb { background: rgba(231,197,119,.22); border-radius: 3px; }

.tank-hero { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; padding-bottom: 11px; border-bottom: 1px solid rgba(168,201,199,.08); }
.tank-hero h3 { margin: 0; font-family: var(--display); font-size: 18px; letter-spacing: 2px; }
.tank-hero p { margin: 3px 0 0; font-size: 7px; color: var(--muted); letter-spacing: .6px; }
.tank-hero .hero-right { text-align: right; }
.tank-hero .hero-right b { display: block; font-size: 14px; color: var(--gold); }
.tank-hero .hero-right span { font-size: 6px; color: var(--dim); letter-spacing: .8px; }

.stat-block { padding: 11px 0 4px; }
.section-label { display: flex; align-items: center; justify-content: space-between; margin: 9px 0 7px; font-size: 6.5px; letter-spacing: 1.6px; color: var(--gold-2); }
.section-label b { color: var(--muted); letter-spacing: .5px; font-weight: 400; }
.water-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px 10px; }
.water-item { padding: 7px 8px; border: 1px solid rgba(168,201,199,.09); border-radius: 4px; background: rgba(15,31,35,.4); }
.water-item .w-label { display: flex; justify-content: space-between; font-size: 6px; color: var(--dim); letter-spacing: .7px; }
.water-item .w-label b { color: var(--cream); font-size: 7px; }
.bar { height: 3px; margin-top: 5px; border-radius: 2px; background: rgba(255,255,255,.07); overflow: hidden; }
.bar i { display: block; height: 100%; border-radius: 2px; background: linear-gradient(90deg, #3f9b7f, #7de2bc); }
.bar.warn i { background: linear-gradient(90deg, #a5782f, #e7c577); }
.bar.bad i { background: linear-gradient(90deg, #9c3b34, #e26857); }

.action-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.action-btn {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 9px 10px 8px;
  border: 1px solid var(--line);
  border-radius: 5px;
  background: linear-gradient(145deg, rgba(22, 43, 47, .55), rgba(9, 20, 23, .6));
  color: #cbd6cf;
  transition: .15s ease;
  text-align: left;
}
.action-btn:hover { border-color: rgba(231,197,119,.4); background: rgba(31, 50, 48, .6); }
.action-btn.active { border-color: var(--teal); background: rgba(50, 112, 93, .22); box-shadow: 0 0 0 1px rgba(114,214,184,.1); }
.action-btn.dim { opacity: .5; }
.action-btn b { font-family: var(--display); font-size: 11px; letter-spacing: 1.3px; color: var(--gold); }
.action-btn span { font-size: 6px; letter-spacing: .4px; color: var(--muted); line-height: 1.3; }
.action-btn .key { position: absolute; }

.roster { display: flex; flex-direction: column; gap: 5px; }
.fish-card {
  position: relative;
  display: flex; align-items: center; gap: 8px;
  padding: 6px 7px;
  border: 1px solid rgba(168,201,199,.1);
  border-radius: 5px;
  background: rgba(14, 29, 33, .44);
  transition: .15s ease;
  cursor: pointer;
  user-select: none;
}
.fish-card:hover { border-color: rgba(231,197,119,.26); }
.fish-card.selected { border-color: var(--teal); background: rgba(55, 117, 95, .17); box-shadow: 0 0 0 1px rgba(114,214,184,.1); }
.fish-card .fish-thumb {
  flex: 0 0 52px; height: 38px; display: grid; place-items: center;
  background: radial-gradient(ellipse, rgba(50, 135, 132, .2), transparent 70%);
}
.fish-card .fish-thumb img { max-width: 52px; max-height: 38px; object-fit: contain; filter: drop-shadow(0 2px 4px rgba(0,0,0,.5)); }
.fish-meta { flex: 1; min-width: 0; }
.fish-line { display: flex; align-items: baseline; gap: 4px; }
.fish-line b { font-family: var(--display); font-size: 10.5px; letter-spacing: .4px; color: var(--cream); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.sex { font-size: 8px; }
.sex.male { color: #7ec2e8; }
.sex.female { color: #e89aa9; }
.fish-sub { display: block; font-size: 6px; color: var(--muted); letter-spacing: .2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 1px; }
.fish-bars { display: flex; align-items: center; gap: 5px; margin-top: 3px; }
.fish-bars .bar { flex: 1; margin: 0; height: 2px; }
.fish-bars em { font-style: normal; font-size: 5.5px; color: var(--dim); }
.fish-sell {
  flex: 0 0 auto; padding: 3px 5px; border: 1px solid rgba(215,94,79,.25); border-radius: 3px;
  color: rgba(226,104,87,.8); font-size: 5.4px; letter-spacing: .5px; background: rgba(30,15,15,.2);
}
.fish-sell:hover { color: #ff9a89; border-color: var(--danger); }
.select-mark {
  position: absolute; top: 5px; right: 5px;
  width: 12px; height: 12px; border-radius: 50%;
  border: 1px solid rgba(143,164,167,.4);
  display: grid; place-items: center;
  font-size: 6px; color: transparent;
}
.fish-card.selected .select-mark { background: var(--teal); border-color: var(--teal); color: #06110f; }
.empty-note { padding: 14px 10px; border: 1px dashed rgba(168,201,199,.15); border-radius: 5px; text-align: center; font-size: 7px; color: var(--dim); line-height: 1.6; }

.egg-panel { margin-top: 8px; padding: 8px 9px; border: 1px solid rgba(231,197,119,.2); border-radius: 4px; background: rgba(67, 52, 21, .12); }
.egg-panel .egg-line { display: flex; justify-content: space-between; font-size: 6.5px; color: var(--gold); letter-spacing: .5px; }
.egg-panel .egg-line span:last-child { color: var(--cream); }
.egg-panel .bar { margin-top: 5px; }
.egg-panel .bar i { background: linear-gradient(90deg, #a97f33, #f0cf7f); }
.egg-panel small { display: block; margin-top: 4px; font-size: 6px; color: var(--dim); line-height: 1.3; }

.breed-box { margin-top: 9px; padding: 9px; border: 1px solid rgba(168,201,199,.1); border-radius: 5px; background: rgba(10, 24, 27, .45); }
.breed-box .breed-note { display: flex; justify-content: space-between; gap: 8px; font-size: 6.5px; color: var(--muted); line-height: 1.4; margin-bottom: 7px; }
.breed-box .breed-note b { color: var(--gold-2); font-weight: 400; }
.breed-box .breed-reason { font-size: 6px; color: var(--dim); margin-top: 5px; line-height: 1.35; min-height: 8px; }
.primary-btn {
  display: block; width: 100%;
  padding: 8px 10px;
  border: 1px solid rgba(114,214,184,.5);
  border-radius: 4px;
  background: linear-gradient(135deg, rgba(114,214,184,.18), rgba(22,64,51,.38));
  color: #9cebc9;
  font-size: 8px; letter-spacing: 1.2px; font-weight: 700;
  transition: .15s;
}
.primary-btn:hover { background: rgba(114,214,184,.23); }
.primary-btn:disabled { opacity: .35; cursor: not-allowed; }
.ghost-btn {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background: rgba(12,27,30,.6);
  color: var(--muted);
  font-size: 7px; letter-spacing: 1px;
}
.ghost-btn:hover { color: var(--cream); border-color: rgba(231,197,119,.35); }

.decor-drawer { margin-top: 8px; border-top: 1px solid var(--line); padding-top: 2px; }
.decor-row { display: flex; align-items: center; gap: 7px; padding: 6px 5px; border: 1px solid rgba(168,201,199,.09); border-radius: 4px; margin-bottom: 4px; background: rgba(15,31,35,.35); }
.decor-row img { width: 34px; height: 30px; object-fit: contain; }
.decor-row .decor-meta { flex: 1; min-width: 0; }
.decor-row b { display: block; font-family: var(--display); font-size: 9px; letter-spacing: .4px; color: var(--cream); }
.decor-row span { font-size: 5.8px; color: var(--dim); }
.decor-row button { padding: 3px 5px; border: 1px solid var(--line); border-radius: 3px; font-size: 5.5px; color: var(--muted); }
.decor-row button.place { color: var(--gold); border-color: rgba(231,197,119,.3); }
.decor-row button.remove { color: #d98a7d; border-color: rgba(215,94,79,.25); }
.decor-empty { font-size: 6.5px; color: var(--dim); line-height: 1.5; padding: 5px 2px 7px; }

/* -------------------------------------------------------------------- help */
.help-card {
  width: min(880px, calc(100vw - 44px));
  max-height: min(760px, calc(100dvh - 44px));
  display: flex;
  flex-direction: column;
  border-radius: 11px;
  overflow: hidden;
}
.help-body {
  overflow-y: auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
  padding: 18px 22px;
  scrollbar-width: thin;
}
.help-body section { padding: 9px 11px; border: 1px solid rgba(168,201,199,.09); border-radius: 5px; background: rgba(13, 29, 33, .35); }
.help-body h3 { margin: 0 0 5px; font-family: var(--display); font-size: 10px; letter-spacing: 1.5px; color: var(--gold); }
.help-body p { margin: 0; font-family: var(--display); font-size: 10px; line-height: 1.5; color: var(--muted); }
.help-body b { color: #cdd9d1; font-weight: 700; }
.help-note { grid-column: 1 / -1; border-color: rgba(231,197,119,.2) !important; background: rgba(67, 52, 21, .1) !important; }
.help-foot { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 12px 22px 16px; border-top: 1px solid var(--line); }
.help-foot span { font-size: 6.5px; color: var(--dim); letter-spacing: 1px; }

/* ------------------------------------------------------------- drag ghost */
.drag-ghost {
  position: fixed;
  z-index: 300;
  width: 76px; height: 64px;
  transform: translate(-50%, -50%);
  border: 1px solid var(--gold);
  border-radius: 6px;
  background: rgba(8, 20, 23, .92);
  box-shadow: 0 12px 30px rgba(0,0,0,.5), 0 0 22px rgba(231,197,119,.2);
  pointer-events: none;
  display: flex; align-items: center; justify-content: center;
}
.drag-ghost img { max-width: 64px; max-height: 50px; object-fit: contain; }
.drag-ghost::after { content: "DROP ON TANK"; position: absolute; bottom: -16px; left: 50%; transform: translateX(-50%); font-size: 5.5px; letter-spacing: .7px; color: var(--gold); white-space: nowrap; }

/* -------------------------------------------------------------- float text */
.float-layer { position: absolute; inset: 0; pointer-events: none; z-index: 90; }
.float-money {
  position: absolute;
  transform: translate(-50%, -50%);
  color: #f6df9b;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: .5px;
  text-shadow: 0 2px 10px rgba(0,0,0,.8), 0 0 14px rgba(231,197,119,.4);
  animation: floatUp 1.1s ease-out both;
  white-space: nowrap;
}
@keyframes floatUp {
  0% { opacity: 0; transform: translate(-50%, -30%) scale(.9); }
  18% { opacity: 1; transform: translate(-50%, -70%) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -170%) scale(1.02); }
}

/* ---------------------------------------------------------------- responsive */
@media (max-width: 1060px) {
  .brand { min-width: 0; }
  .brand-text span { display: none; }
  .detail-card { grid-template-columns: minmax(0, 1fr) 340px; }
  .shop-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
}

@media (max-width: 860px) {
  .detail-card {
    grid-template-columns: 1fr;
    grid-template-rows: minmax(250px, 43%) 1fr;
    height: calc(100dvh - 20px);
    width: calc(100vw - 20px);
  }
  .detail-stage { border-right: 0; border-bottom: 1px solid var(--line); }
  .detail-side { min-height: 0; }
  .stage-head h2 { font-size: 20px; letter-spacing: 2.5px; }
  .modal { padding: 10px; }
  .help-body { grid-template-columns: 1fr; }
}

@media (max-width: 760px) {
  .topbar { padding: 8px 9px 14px; gap: 6px; }
  .brand { gap: 7px; }
  .brand-mark { width: 34px; height: 34px; border-radius: 6px; }
  .brand-mark svg { width: 25px; height: 18px; }
  .brand-text h1 { font-size: 15px; letter-spacing: 2.2px; }
  .brand-text span { display: none; }
  .day-chip { padding: 5px 7px; gap: 5px; font-size: 7px; }
  .day-chip .day-label { display: none; }
  .day-chip strong { font-size: 10px; }
  .day-chip .clock { font-size: 9px; }
  .top-actions { gap: 5px; }
  .icon-btn { width: 30px; height: 30px; font-size: 14px; }
  #soundBtn { display: none; }
  .wallet { min-width: 112px; padding: 5px 8px 6px 25px; }
  .wallet .wallet-label { left: 26px; font-size: 5px; }
  .wallet strong { font-size: 12px; }
  .wallet em { font-size: 6px; }
  .wallet-coin { left: 8px; width: 12px; height: 12px; }
  .food-rail { left: 8px; top: 66px; width: 54px; gap: 6px; }
  .rail-head { font-size: 5.5px; letter-spacing: 1.2px; padding: 0 2px; }
  .food-btn { height: 50px; gap: 1px; padding: 3px 2px; border-radius: 6px; }
  .food-btn .food-icon { width: 21px; height: 21px; }
  .food-btn .food-name { display: none; }
  .food-btn .food-count { font-size: 5.8px; top: 2px; right: 2px; min-width: 12px; }
  .food-btn.active { transform: translateX(2px); }
  .rail-foot { display: none; }
  .hint { left: 66px; bottom: 106px; font-size: 7px; padding: 5px 9px; max-width: calc(100vw - 80px); }
  .toast-stack { top: 54px; right: 8px; width: min(270px, calc(100vw - 74px)); }
  .toast { font-size: 7.5px; padding: 7px 9px; }
  .tray { left: 6px; right: 6px; bottom: 6px; height: 80px; gap: 6px; padding: 6px; }
  .tray-head { display: none; }
  .tray-slot { flex: 0 0 44px; width: 44px; height: 60px; }
  .tray-slot img { width: 34px; height: 27px; }
  .tray-slot .decor-img { width: 28px; height: 28px; }
  .tray-slot .tray-name { display: none; }
  .tray-slot .tray-tag { display: none; }
  .tray-actions { flex: 0 0 92px; }
  .shop-button { gap: 5px; }
  .shop-button svg { width: 17px; height: 17px; }
  .shop-button b { font-size: 10px; letter-spacing: 1px; }
  .shop-button small { display: none; }
  .shop-card { width: calc(100vw - 16px); height: calc(100dvh - 16px); border-radius: 8px; }
  .modal { padding: 8px; }
  .modal-head { padding: 12px 12px 10px; gap: 8px; }
  .modal-head h2 { font-size: 17px; letter-spacing: 2px; }
  .shop-wallet { padding: 4px 6px; }
  .shop-wallet span { display: none; }
  .shop-wallet strong { font-size: 10px; }
  .shop-tabs { padding: 8px 10px 0; gap: 2px; }
  .shop-tabs button { padding: 7px 11px 8px; font-size: 7px; letter-spacing: 1px; }
  .shop-toolbar { padding: 9px 10px; flex-direction: column; align-items: flex-start; gap: 7px; }
  .shop-toolbar p { display: none; }
  .shop-grid { padding: 10px; grid-template-columns: 1fr; gap: 8px; }
  .shop-card-item { min-height: 0; }
  .card-art { height: 84px; }
  .card-body { padding: 7px 9px 8px; }
  .card-body .card-name { font-size: 12px; }
  .card-body .card-desc { display: none; }
  .pack-card .card-art { height: 76px; }
  .detail-card { width: 100vw; height: 100dvh; border-radius: 0; grid-template-rows: 43% 1fr; }
  .detail-stage { border-radius: 0; }
  .stage-head { top: 10px; left: 10px; right: 10px; }
  .stage-chips span { font-size: 5.5px; padding: 3px 5px; }
  .stage-chips span:first-child { display: none; }
  .stage-hud { left: 8px; right: 8px; bottom: 8px; padding: 7px 8px; }
  .inspect-hud { flex-direction: column; align-items: flex-start; gap: 5px; }
  .inspect-hud small { display: none; }
  .inspect-grid { gap: 8px; }
  .inspect-grid b { font-size: 8px; }
  .clean-hud { gap: 8px; }
  .hud-copy span { font-size: 6.5px; }
  .hud-progress { min-width: 106px; }
  .decor-hud { gap: 6px; }
  .decor-hud .hud-copy span { display: none; }
  .hud-buttons .primary-btn, .hud-buttons .ghost-btn { padding: 6px 7px; font-size: 6px; }
  .side-scroll { padding: 10px 12px 22px; }
  .stage-head h2 { font-size: 18px; }
  .help-card { width: calc(100vw - 16px); max-height: calc(100dvh - 16px); border-radius: 8px; }
  .help-body { padding: 10px; }
  .help-foot { padding: 9px 10px 12px; flex-direction: column; align-items: flex-start; gap: 6px; }
  .float-money { font-size: 11px; }
}

@media (max-height: 620px) and (orientation: landscape) {
  .topbar { padding: 6px 10px 10px; }
  .brand-text h1 { font-size: 15px; }
  .food-rail { top: 58px; }
  .food-btn { height: 48px; }
  .tray { height: 70px; }
  .hint { display: none; }
  .detail-card { height: calc(100dvh - 12px); }
  .detail-stage { min-height: 220px; }
}

import {
  SPECIES, SPECIES_LIST, FOODS, FOOD_ORDER, DECOR, DECOR_LIST
} from './data.js';
import {
  feedTank, cleanTank, collectDrop, buyFish, buyFood, buyDecor,
  placeTrayFish, placeDecorInTank, moveDecor, removeDecor, sellFish,
  breedPair, sellTrayItem, tankById, happinessOf, stageOf, beautyOf,
  formatMoney, formatClock, saveGame, resetGame
} from './game.js';
import { fishThumb, decorThumb, foodIcon } from './art.js';
import { TankView } from './render.js';

const $ = (id) => document.getElementById(id);
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));

export class UI {
  constructor(state, renderer) {
    this.state = state;
    this.renderer = renderer;
    this.sceneCanvas = $('scene');
    this.detailCanvas = $('detailCanvas');
    this.detailView = new TankView(this.detailCanvas, state);
    this.detailOpen = false;
    this.detailTankId = null;
    this.detailMode = null;
    this.selectedFish = [];
    this.selectedTray = null;
    this.ghost = null;
    this.pointer = { x: 0, y: 0 };
    this.cleaning = false;
    this.lastScrub = 0;
    this.scrubbing = false;
    this.drag = null;
    this.suppressClick = false;
    this.shopTab = 'fish';
    this.shopFilter = 'all';
    this.activeModal = null;
    this.lastTick = 0;
    this.audio = null;
    this.hintTimer = null;

    this.buildStaticUI();
    this.bindEvents();
    this.updateAll();
    this.setHint('Tap a tank to inspect, feed and clean.', 9000);
    setTimeout(() => this.hideHint(), 9000);
    this.updateSoundButton();
  }

  // --------------------------------------------------------------- static UI
  buildStaticUI() {
    $('foodItems').innerHTML = FOOD_ORDER.map(id => {
      const f = FOODS[id];
      return `<button class="food-btn" data-food="${id}" title="${f.name} — ${f.desc}">
        <span class="food-icon">${foodIcon(id)}</span>
        <span class="food-name">${f.short}</span>
        <span class="food-count">${this.state.foods[id] || 0}</span>
      </button>`;
    }).join('');
    this.renderTray();
  }

  updateAll() {
    this.updateWallet();
    this.updateFoods();
    this.renderTray();
    this.updateClock();
  }

  setHint(text, duration = 6500) {
    const el = $('hint');
    $('hintText').textContent = text;
    el.classList.remove('hide');
    clearTimeout(this.hintTimer);
    if (duration) this.hintTimer = setTimeout(() => this.hideHint(), duration);
  }

  hideHint() {
    $('hint').classList.add('hide');
  }

  updateWallet() {
    const txt = formatMoney(this.state.money);
    $('moneyValue').textContent = txt;
    $('shopMoney').textContent = txt;
  }

  flashWallet() {
    const w = $('wallet');
    w.classList.remove('flash');
    void w.offsetWidth;
    w.classList.add('flash');
    setTimeout(() => w.classList.remove('flash'), 620);
  }

  updateClock() {
    $('dayValue').textContent = this.state.day;
    $('clockValue').textContent = formatClock(this.state);
  }

  updateSoundButton() {
    const btn = $('soundBtn');
    btn.classList.toggle('muted', !this.state.sound);
    btn.title = this.state.sound ? 'Mute sound' : 'Enable sound';
  }

  // ---------------------------------------------------------------- food rail
  updateFoods() {
    document.querySelectorAll('.food-btn').forEach(btn => {
      const id = btn.dataset.food;
      const count = this.state.foods[id] || 0;
      btn.classList.toggle('active', id === this.state.selectedFood);
      btn.classList.toggle('empty', count <= 0);
      btn.querySelector('.food-count').textContent = count;
    });
    const f = FOODS[this.state.selectedFood];
    $('railHint').textContent = `${f.short} · ${this.state.foods[this.state.selectedFood] || 0}`;
    document.querySelectorAll('[data-food-count]').forEach(el => {
      el.textContent = this.state.foods[el.dataset.foodCount] || 0;
    });
    document.querySelectorAll('.food-quick [data-food]').forEach(el => {
      el.classList.toggle('active', el.dataset.food === this.state.selectedFood);
    });
  }

  selectFood(id) {
    this.state.selectedFood = id;
    this.updateFoods();
    this.ensureAudio();
    this.sfx('click');
    const f = FOODS[id];
    this.setHint(`${f.name} in hand · open a tank and press FEED.`);
    if (this.detailOpen) this.renderDetail();
  }

  // --------------------------------------------------------------------- tray
  traySlotHTML(item) {
    if (!item) return `<div class="tray-slot empty" aria-hidden="true"></div>`;
    if (item.kind === 'fish') {
      const sp = SPECIES[item.speciesId];
      return `<div class="tray-slot ${this.selectedTray === item.uid ? 'selected' : ''}" data-uid="${item.uid}" title="${sp.name}">
        <span class="tray-tag">${sp.group === 'predator' ? 'PRED' : 'NANO'}</span>
        <img src="${fishThumb(item.speciesId)}" alt="">
        <span class="tray-name">${sp.name}</span>
        <button class="tray-remove" data-remove="${item.uid}" aria-label="Return ${sp.name}">✕</button>
      </div>`;
    }
    const d = DECOR[item.decorType];
    return `<div class="tray-slot ${this.selectedTray === item.uid ? 'selected' : ''}" data-uid="${item.uid}" title="${d.name}">
      <span class="tray-tag">DECOR</span>
      <img class="decor-img" src="${decorThumb(item.decorType)}" alt="">
      <span class="tray-name">${d.name}</span>
      <button class="tray-remove" data-remove="${item.uid}" aria-label="Return ${d.name}">✕</button>
    </div>`;
  }

  renderTray() {
    const items = this.state.tray;
    if (this.selectedTray && !items.find(i => i.uid === this.selectedTray)) this.selectedTray = null;
    const slots = [];
    for (const item of items) slots.push(this.traySlotHTML(item));
    for (let i = items.length; i < 10; i++) slots.push(this.traySlotHTML(null));
    $('trayItems').innerHTML = slots.join('');
    $('trayCount').textContent = `${items.length} / 10`;
    this.syncRendererSelection();
  }

  syncRendererSelection() {
    const item = this.state.tray.find(i => i.uid === this.selectedTray);
    this.renderer.selection = item ? { kind: item.kind, speciesId: item.speciesId, decorType: item.decorType } : null;
  }

  selectTray(uid) {
    if (this.selectedTray === uid) {
      this.selectedTray = null;
      this.syncRendererSelection();
      this.renderTray();
      this.setHint('Selection cleared.');
      return;
    }
    const item = this.state.tray.find(i => i.uid === uid);
    if (!item) return;
    this.selectedTray = uid;
    this.syncRendererSelection();
    this.renderTray();
    this.ensureAudio();
    this.sfx('click');
    if (item.kind === 'fish') {
      const sp = SPECIES[item.speciesId];
      this.setHint(`${sp.name} selected · tap a ${sp.group === 'predator' ? '200 cm predator' : '50 cm nano'} tank, or drag it in.`);
    } else {
      this.setHint(`${DECOR[item.decorType].name} selected · tap a tank to choose its spot.`);
    }
  }

  toggleTray(uid) {
    this.selectTray(uid);
  }

  // -------------------------------------------------------------------- audio
  ensureAudio() {
    if (this.audio) return;
    try {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (Ctx) this.audio = new Ctx();
    } catch (e) { /* audio unavailable */ }
  }

  tone(freq, dur, type = 'sine', vol = 0.035, delay = 0, slide = 0) {
    if (!this.state.sound) return;
    this.ensureAudio();
    if (!this.audio) return;
    if (this.audio.state === 'suspended') this.audio.resume();
    const t0 = this.audio.currentTime + delay;
    const osc = this.audio.createOscillator();
    const g = this.audio.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t0 + dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g);
    g.connect(this.audio.destination);
    osc.start(t0);
    osc.stop(t0 + dur + 0.02);
  }

  sfx(kind) {
    if (!this.state.sound) return;
    switch (kind) {
      case 'coin': this.tone(920, 0.08, 'sine', 0.03); this.tone(1380, 0.12, 'sine', 0.025, 0.06); break;
      case 'feed': this.tone(380, 0.08, 'triangle', 0.028); this.tone(520, 0.1, 'triangle', 0.02, 0.06); break;
      case 'buy': this.tone(440, 0.07, 'triangle', 0.025); this.tone(660, 0.08, 'triangle', 0.02, 0.06); this.tone(880, 0.12, 'triangle', 0.016, 0.12); break;
      case 'place': this.tone(300, 0.08, 'sine', 0.03); this.tone(480, 0.12, 'sine', 0.02, 0.05); break;
      case 'clean': this.tone(240, 0.07, 'sawtooth', 0.012); this.tone(360, 0.1, 'sine', 0.02, 0.05); break;
      case 'error': this.tone(150, 0.14, 'square', 0.018, 0, -30); break;
      default: this.tone(360, 0.045, 'sine', 0.016);
    }
  }

  // ------------------------------------------------------------------ toasts
  toast(message, kind = 'info') {
    if (!message) return;
    const stack = $('toasts');
    const el = document.createElement('div');
    el.className = `toast ${kind}`;
    const icon = kind === 'bad' ? '!' : kind === 'good' ? '✓' : '◆';
    el.innerHTML = `<span class="toast-icon">${icon}</span><span>${message}</span>`;
    stack.appendChild(el);
    while (stack.children.length > 4) stack.firstElementChild.remove();
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 280);
    }, 3900);
  }

  floatMoney(text, clientX, clientY) {
    const el = document.createElement('div');
    el.className = 'float-money';
    el.textContent = text;
    const shell = $('gameShell').getBoundingClientRect();
    el.style.left = `${clientX - shell.left}px`;
    el.style.top = `${clientY - shell.top}px`;
    $('floatLayer').appendChild(el);
    setTimeout(() => el.remove(), 1150);
  }

  // ------------------------------------------------------------------ modals
  openShop() {
    this.ensureAudio();
    this.sfx('click');
    $('shopModal').hidden = false;
    this.activeModal = 'shop';
    this.renderShop();
  }

  openHelp() {
    $('helpModal').hidden = false;
    this.activeModal = 'help';
  }

  closeModal(name = this.activeModal) {
    if (name === 'shop') $('shopModal').hidden = true;
    if (name === 'help') $('helpModal').hidden = true;
    if (name === 'detail') this.closeDetail();
    if (this.activeModal === name) this.activeModal = null;
  }

  closeAllModals() {
    $('shopModal').hidden = true;
    $('helpModal').hidden = true;
    if (this.detailOpen) this.closeDetail();
    this.activeModal = null;
  }

  // ---------------------------------------------------------------- render shop
  renderShop() {
    const isFish = this.shopTab === 'fish';
    $('fishFilters').hidden = !isFish;
    document.querySelectorAll('#shopTabs button').forEach(b => b.classList.toggle('active', b.dataset.tab === this.shopTab));
    document.querySelectorAll('#fishFilters button').forEach(b => b.classList.toggle('active', b.dataset.filter === this.shopFilter));
    const trayFull = this.state.tray.length >= 10;
    let html = '';
    if (isFish) {
      $('shopNote').textContent = 'Predators need the 2 m rack. Nano fish belong in the 50 cm rack.';
      const list = SPECIES_LIST.filter(sp => this.shopFilter === 'all' || sp.group === this.shopFilter);
      html = list.map(sp => {
        const disabled = this.state.money < sp.price || trayFull;
        const tag = sp.group === 'predator' ? 'PREDATOR' : 'NANO';
        const foodTag = sp.group === 'predator' ? 'LIVE FOOD' : 'PELLETS OK';
        return `<article class="shop-card-item">
          <div class="card-art">
            <span class="art-badge">${tag}</span>
            <span class="art-price">${formatMoney(sp.price)}</span>
            <img src="${fishThumb(sp.id)}" alt="${sp.name}">
          </div>
          <div class="card-body">
            <div class="card-name">${sp.name}</div>
            <div class="card-vi">${sp.vi}</div>
            <p class="card-desc">${sp.desc}</p>
            <div class="card-tags">
              <span>${sp.sizeCm} CM</span>
              <span>${tag} RACK</span>
              <span>${foodTag}</span>
              <span>${sp.personality}</span>
            </div>
            <button class="card-buy" data-buy-fish="${sp.id}" ${disabled ? 'disabled' : ''}>
              <span>ADD TO TRAY</span><small>${formatMoney(sp.price)} VNĐ</small>
            </button>
          </div>
        </article>`;
      }).join('');
    } else if (this.shopTab === 'food') {
      $('shopNote').textContent = 'One use feeds one tank. Predators refuse pellets — restock live prey and shrimp.';
      html = FOOD_ORDER.map(id => {
        const f = FOODS[id];
        const disabled = this.state.money < f.price;
        return `<article class="shop-card-item pack-card">
          <div class="card-art">
            <span class="art-badge">${f.group === 'predator' ? 'PREDATOR ONLY' : f.group === 'small' ? 'NANO ONLY' : 'ALL FISH'}</span>
            <span class="art-price">${formatMoney(f.price)}</span>
            <div class="food-big" style="width:66px;height:66px">${foodIcon(id)}</div>
          </div>
          <div class="card-body">
            <div class="card-name">${f.name}</div>
            <div class="card-vi">${f.vi} · +${f.pack} uses</div>
            <p class="card-desc">${f.desc}</p>
            <div class="stock-line"><span>IN STOCK</span><b>${this.state.foods[id] || 0} uses</b></div>
            <div class="stock-line"><span>SATIETY</span><b>+${f.boost}</b></div>
            <button class="card-buy" data-buy-food="${id}" ${disabled ? 'disabled' : ''}>
              <span>RESTOCK</span><small>${formatMoney(f.price)} VNĐ</small>
            </button>
          </div>
        </article>`;
      }).join('');
    } else {
      $('shopNote').textContent = 'Decor is sold to the holding tray. Drag it onto a tank for a custom position.';
      html = DECOR_LIST.map(d => {
        const disabled = this.state.money < d.price || trayFull;
        return `<article class="shop-card-item pack-card">
          <div class="card-art">
            <span class="art-badge">AQUASCAPE</span>
            <span class="art-price">${formatMoney(d.price)}</span>
            <img src="${decorThumb(d.id)}" alt="${d.name}" style="max-width:58%;max-height:88%">
          </div>
          <div class="card-body">
            <div class="card-name">${d.name}</div>
            <div class="card-vi">${d.vi} · +${d.beauty} beauty</div>
            <p class="card-desc">${d.desc}</p>
            <div class="card-tags"><span>+${d.beauty} BEAUTY</span><span>ANY TANK</span></div>
            <button class="card-buy" data-buy-decor="${d.id}" ${disabled ? 'disabled' : ''}>
              <span>ADD TO TRAY</span><small>${formatMoney(d.price)} VNĐ</small>
            </button>
          </div>
        </article>`;
      }).join('');
    }
    $('shopGrid').innerHTML = html;
  }

  // ------------------------------------------------------------------- detail
  openTank(tankId, options = {}) {
    const tank = tankById(this.state, tankId);
    if (!tank) return;
    this.detailTankId = tankId;
    this.detailOpen = true;
    this.detailMode = null;
    this.selectedFish = [];
    this.ghost = null;
    this.scrubbing = false;
    $('detailModal').hidden = false;
    this.activeModal = 'detail';
    requestAnimationFrame(() => {
      this.detailView.resize();
      this.pointer = { x: this.detailView.w / 2, y: this.detailView.h / 2 };
      this.renderDetail();
      if (options.decorTrayUid) {
        this.startDecorFromTray(options.decorTrayUid, options.nx, options.ny);
      }
    });
  }

  closeDetail() {
    $('detailModal').hidden = true;
    this.detailOpen = false;
    this.detailTankId = null;
    this.detailMode = null;
    this.ghost = null;
    this.selectedFish = [];
    this.scrubbing = false;
    $('detailStage').classList.remove('mode-clean');
    if (this.activeModal === 'detail') this.activeModal = null;
  }

  renderDetail() {
    if (!this.detailOpen) return;
    const tank = tankById(this.state, this.detailTankId);
    if (!tank) { this.closeDetail(); return; }
    this.selectedFish = this.selectedFish.filter(id => tank.fish.some(f => f.id === id));
    $('stageCode').textContent = `${tank.code} · ${tank.sizeCm} CM · ${tank.kind === 'large' ? 'PREDATOR' : 'NANO'}`;
    $('detailTitle').textContent = tank.name;
    $('stageTemp').textContent = `${tank.temp.toFixed(1)}°C`;
    $('stageCap').textContent = `${tank.fish.length} / ${tank.capacity}`;
    const filterEl = $('stageFilter');
    filterEl.textContent = tank.filter ? 'FILTER ON' : 'NO FILTER';
    filterEl.classList.toggle('off', !tank.filter);
    $('cleanHud').hidden = this.detailMode !== 'clean';
    $('inspectHud').hidden = this.detailMode !== 'inspect';
    $('decorHud').hidden = this.detailMode !== 'decor';
    $('detailStage').classList.toggle('mode-clean', this.detailMode === 'clean');
    const scroll = $('detailSideBody')?.scrollTop || 0;
    $('detailSideBody').innerHTML = this.detailSideHTML(tank);
    $('detailSideBody').scrollTop = scroll;
    this.updateDecorHud();
    this.refreshDetailDynamic();
  }

  detailSideHTML(tank) {
    const food = FOODS[this.state.selectedFood];
    const foodCount = this.state.foods[this.state.selectedFood] || 0;
    const wrongFood = (food.group === 'predator' && tank.kind !== 'large') || (food.group === 'small' && tank.kind === 'large');
    const clarity = Math.round(tank.cleanliness);
    const ph = (tank.ph - (100 - tank.cleanliness) / 100 * 0.35).toFixed(2);
    const cleanWord = clarity > 65 ? 'CLEAR' : clarity > 35 ? 'CLOUDY' : 'DIRTY';
    const clarityClass = clarity > 65 ? '' : clarity > 35 ? 'warn' : 'bad';
    const pair = this.pairState(tank);
    const eggs = tank.eggs[0];
    const fishCards = tank.fish.map(f => {
      const sp = SPECIES[f.speciesId];
      const selected = this.selectedFish.includes(f.id);
      const happy = happinessOf(f, tank);
      let sexSym = f.sex === 'male' ? '♂' : '♀';
      return `<div class="fish-card ${selected ? 'selected' : ''}" data-fish="${f.id}" role="button" tabindex="0" aria-pressed="${selected}">
        <div class="fish-thumb"><img src="${fishThumb(f.speciesId)}" alt=""></div>
        <div class="fish-meta">
          <div class="fish-line"><b>${f.name}</b><span class="sex ${f.sex}">${sexSym}</span></div>
          <span class="fish-sub">${sp.name} · ${stageOf(f).toUpperCase()} · ${happy}% happy</span>
          <div class="fish-bars"><div class="bar"><i data-full="${f.id}" style="width:${Math.round(f.fullness)}%"></i></div><em>FULL ${Math.round(f.fullness)}%</em></div>
        </div>
        <button class="fish-sell" data-sell="${f.id}" title="Sell this fish">SELL</button>
        <span class="select-mark">✓</span>
      </div>`;
    }).join('') || `<div class="empty-note">This tank is empty.<br>Buy a fish and place it from the holding tray.</div>`;

    const trayDecor = this.state.tray.filter(i => i.kind === 'decor');
    const decorRows = trayDecor.map(item => {
      const d = DECOR[item.decorType];
      return `<div class="decor-row">
        <img src="${decorThumb(item.decorType)}" alt="">
        <div class="decor-meta"><b>${d.name}</b><span>In tray · +${d.beauty} beauty</span></div>
        <button class="place" data-decor-tray="${item.uid}">PLACE</button>
      </div>`;
    }).join('');
    const tankRows = tank.decor.map((d, i) => {
      const def = DECOR[d.type];
      return `<div class="decor-row">
        <img src="${decorThumb(d.type)}" alt="">
        <div class="decor-meta"><b>${def.name}</b><span>Placed · +${def.beauty} beauty</span></div>
        <button data-decor-existing="${i}">MOVE</button>
        <button class="remove" data-decor-remove="${i}">SELL</button>
      </div>`;
    }).join('');

    const quickFood = FOOD_ORDER.map(id => {
      const f = FOODS[id];
      const count = this.state.foods[id] || 0;
      return `<button data-food="${id}" class="${id === this.state.selectedFood ? 'active' : ''} ${count <= 0 ? 'empty' : ''}" title="${f.name}">
        <span>${foodIcon(id)}</span><b>${f.short.split(' ')[0]}</b><em data-food-count="${id}">${count}</em>
      </button>`;
    }).join('');

    return `
      <div class="tank-hero">
        <div>
          <h3>${tank.name}</h3>
          <p>${tank.code} · ${tank.sizeCm} CM · ${tank.kind === 'large' ? 'PREDATOR RACK' : 'NANO RACK'}</p>
        </div>
        <div class="hero-right"><b>${tank.fish.length}/${tank.capacity}</b><span>BIOLOAD</span></div>
      </div>

      <div class="stat-block">
        <div class="section-label">WATER QUALITY <b id="clarityLabel">${clarity}% ${cleanWord}</b></div>
        <div class="water-grid">
          <div class="water-item">
            <div class="w-label"><span>CLARITY</span><b id="wClarityVal">${clarity}%</b></div>
            <div class="bar ${clarityClass}"><i id="wClarityBar" style="width:${clarity}%"></i></div>
          </div>
          <div class="water-item">
            <div class="w-label"><span>TEMP</span><b id="wTempVal">${tank.temp.toFixed(1)}°C</b></div>
            <div class="bar"><i style="width:${clamp((tank.temp - 20) / 12 * 100, 10, 100)}%"></i></div>
          </div>
          <div class="water-item">
            <div class="w-label"><span>pH</span><b id="wPhVal">${ph}</b></div>
            <div class="bar"><i style="width:${clamp((parseFloat(ph) / 9) * 100, 20, 90)}%"></i></div>
          </div>
          <div class="water-item">
            <div class="w-label"><span>OXYGEN</span><b id="wO2Val">${Math.round(tank.oxygen)}%</b></div>
            <div class="bar"><i id="wO2Bar" style="width:${Math.round(tank.oxygen)}%"></i></div>
          </div>
        </div>
        <div class="section-label">BEAUTY <b>${beautyOf(tank)} / 100 · ${tank.decor.length}/9 DECOR</b></div>
      </div>

      <div class="section-label">CARE <b>${this.state.selectedFood.toUpperCase()}</b></div>
      <div class="action-grid">
        <button class="action-btn ${wrongFood || foodCount <= 0 ? 'dim' : ''}" data-action="feed">
          <b>FEED</b><span>${wrongFood ? '✕ WRONG FOOD' : foodCount <= 0 ? 'OUT OF STOCK' : `${food.name} · ${foodCount} left`}</span>
        </button>
        <button class="action-btn ${this.detailMode === 'clean' ? 'active' : ''}" data-action="clean">
          <b>CLEAN</b><span>Scrub glass · ${clarity}%</span>
        </button>
        <button class="action-btn ${this.detailMode === 'inspect' ? 'active' : ''}" data-action="inspect">
          <b>INSPECT</b><span>2.15× water lens</span>
        </button>
        <button class="action-btn ${this.detailMode === 'decor' ? 'active' : ''}" data-action="decor">
          <b>DECORATE</b><span>${tank.decor.length}/9 pieces</span>
        </button>
      </div>
      <div class="food-quick">${quickFood}</div>

      <div class="section-label">RESIDENTS <b>${tank.fish.length} FISH</b></div>
      <div class="roster">${fishCards}</div>

      ${eggs ? `<div class="egg-panel">
        <div class="egg-line"><span>EGG CLUTCH × ${eggs.count || 2}</span><span id="eggTimer">${this.formatEgg(eggs.timer)}</span></div>
        <div class="bar"><i id="eggBar" style="width:${(1 - eggs.timer / (eggs.total || 38)) * 100}%"></i></div>
        <small>${SPECIES[eggs.speciesId]?.name || 'Unknown'} · parents ${eggs.parents?.join(' × ') || '—'}</small>
      </div>` : ''}

      <div class="breed-box">
        <div class="breed-note"><span>BREEDING PAIR</span><b>${pair.ok ? 'READY' : 'NOT READY'}</b></div>
        <div class="breed-note">
          <span>${this.selectedFish.length ? this.selectedFish.map(id => tank.fish.find(f => f.id === id)?.name).filter(Boolean).join(' × ') : 'Select one male and one female.'}</span>
          <b>FEE 50.000</b>
        </div>
        <button class="primary-btn" id="breedBtn" data-breed ${pair.ok ? '' : 'disabled'}>BREED PAIR</button>
        <div class="breed-reason" id="breedReason">${pair.reason}</div>
      </div>

      ${this.detailMode === 'decor' ? `<div class="decor-drawer">
        <div class="section-label">DECOR FROM TRAY <b>${trayDecor.length}</b></div>
        ${decorRows || `<div class="decor-empty">No loose decor. Buy driftwood, stone or plants from the shop.</div>`}
        <div class="section-label">IN THIS TANK <b>${tank.decor.length}/9</b></div>
        ${tankRows || `<div class="decor-empty">Bare substrate. Place something to raise beauty and tips.</div>`}
      </div>` : ''}
    `;
  }

  formatEgg(timer) {
    const s = Math.max(0, Math.ceil(timer));
    return `0:${String(s).padStart(2, '0')}`;
  }

  pairState(tank) {
    const fishes = this.selectedFish.map(id => tank.fish.find(f => f.id === id)).filter(Boolean);
    if (fishes.length < 2) return { ok: false, reason: 'Select two adult fish — one male, one female.' };
    const [a, b] = fishes;
    if (a.id === b.id) return { ok: false, reason: 'Choose two different fish.' };
    if (a.speciesId !== b.speciesId) return { ok: false, reason: 'Both parents must be the same species.' };
    if (a.sex === b.sex) return { ok: false, reason: 'You need one male and one female.' };
    if (a.growth < 0.95 || b.growth < 0.95) return { ok: false, reason: 'Both fish must be fully grown.' };
    if (a.fullness < 55 || b.fullness < 55) return { ok: false, reason: 'Feed both fish to at least 55% fullness.' };
    if (tank.cleanliness < 55) return { ok: false, reason: 'Water is too dirty to spawn. Clean the tank.' };
    if (a.cooldown > 0 || b.cooldown > 0) return { ok: false, reason: 'This pair needs more rest before spawning again.' };
    if (tank.eggs.length) return { ok: false, reason: 'A clutch is already incubating here.' };
    if (this.state.money < 50000) return { ok: false, reason: 'Need 50.000 VNĐ for the breeding fee.' };
    return { ok: true, reason: 'Ready — a clutch will hatch in about 38 seconds.' };
  }

  refreshDetailDynamic() {
    if (!this.detailOpen) return;
    const tank = tankById(this.state, this.detailTankId);
    if (!tank) return;
    const clarity = Math.round(tank.cleanliness);
    const ph = (tank.ph - (100 - tank.cleanliness) / 100 * 0.35).toFixed(2);
    $('stageTemp').textContent = `${tank.temp.toFixed(1)}°C`;
    $('stageCap').textContent = `${tank.fish.length} / ${tank.capacity}`;
    const clarityLabel = $('clarityLabel');
    if (clarityLabel) clarityLabel.textContent = `${clarity}% ${clarity > 65 ? 'CLEAR' : clarity > 35 ? 'CLOUDY' : 'DIRTY'}`;
    const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
    set('wClarityVal', `${clarity}%`);
    set('wTempVal', `${tank.temp.toFixed(1)}°C`);
    set('wPhVal', ph);
    set('wO2Val', `${Math.round(tank.oxygen)}%`);
    const cb = $('wClarityBar');
    if (cb) {
      cb.style.width = `${clarity}%`;
      const bar = cb.parentElement;
      bar.classList.toggle('warn', clarity <= 65 && clarity > 35);
      bar.classList.toggle('bad', clarity <= 35);
    }
    const ob = $('wO2Bar');
    if (ob) ob.style.width = `${Math.round(tank.oxygen)}%`;
    // fullness bars
    document.querySelectorAll('[data-full]').forEach(el => {
      const fish = tank.fish.find(f => f.id === el.dataset.full);
      if (fish) el.style.width = `${Math.round(fish.fullness)}%`;
    });
    // cleaning hud
    const cleanBar = $('cleanBar');
    if (cleanBar) cleanBar.style.backgroundSize = `${clarity}% 100%`;
    const cleanPct = $('cleanPct');
    if (cleanPct) cleanPct.textContent = `${clarity}%`;
    // inspect hud
    set('inspectTemp', `${tank.temp.toFixed(1)}°C`);
    set('inspectPh', ph);
    set('inspectO2', `${Math.round(tank.oxygen)}%`);
    set('inspectClarity', `${clarity}%`);
    // eggs
    const egg = tank.eggs[0];
    if (egg) {
      set('eggTimer', this.formatEgg(egg.timer));
      const eb = $('eggBar');
      if (eb) eb.style.width = `${clamp((1 - egg.timer / (egg.total || 38)) * 100, 0, 100)}%`;
    }
    // breeding
    const pair = this.pairState(tank);
    const breedBtn = $('breedBtn');
    const reason = $('breedReason');
    if (breedBtn) breedBtn.disabled = !pair.ok;
    if (reason) reason.textContent = pair.reason;
  }

  updateDecorHud() {
    const hudTitle = $('decorHudTitle');
    const hudText = $('decorHudText');
    const confirm = $('decorConfirm');
    if (!hudTitle) return;
    if (!this.ghost) {
      hudTitle.textContent = 'DECORATE TANK';
      hudText.textContent = 'Pick a piece from the side panel, then drag it over the substrate.';
      confirm.disabled = true;
      return;
    }
    const d = DECOR[this.ghost.type];
    hudTitle.textContent = `${this.ghost.source === 'existing' ? 'MOVE' : 'PLACE'} ${d.name.toUpperCase()}`;
    hudText.textContent = this.ghost.valid === false
      ? 'Move the piece back over the water.'
      : 'Drag to position on the substrate, then confirm placement.';
    confirm.disabled = this.ghost.valid === false;
  }

  enterMode(mode) {
    if (this.detailMode === mode) {
      this.detailMode = null;
    } else {
      this.detailMode = mode;
    }
    this.ghost = null;
    this.scrubbing = false;
    if (this.detailMode === 'inspect') {
      this.pointer = { x: this.detailView.w / 2, y: this.detailView.h / 2 };
    }
    this.ensureAudio();
    this.sfx('click');
    this.renderDetail();
  }

  startDecorFromTray(uid, nx = 0.5, ny = 0.94) {
    const item = this.state.tray.find(i => i.uid === uid && i.kind === 'decor');
    if (!item) return;
    this.detailMode = 'decor';
    this.ghost = {
      source: 'tray', trayUid: uid, type: item.decorType,
      x: clamp(nx, 0.08, 0.92), y: clamp(ny, 0.8, 0.98),
      flip: Math.random() < 0.5, valid: true
    };
    this.renderDetail();
  }

  startDecorExisting(index) {
    const tank = tankById(this.state, this.detailTankId);
    const d = tank?.decor[index];
    if (!d) return;
    this.detailMode = 'decor';
    this.ghost = {
      source: 'existing', index, type: d.type,
      x: d.x, y: d.y, flip: d.flip, valid: true
    };
    this.renderDetail();
  }

  updateGhostFromPointer(px, py) {
    if (!this.ghost) return;
    const water = this.detailView.hit.water;
    if (!water) return;
    const inside = this.detailView.inWater(px, py);
    this.ghost.valid = inside;
    this.ghost.x = clamp((px - water.x) / water.w, 0.08, 0.92);
    this.ghost.y = clamp((py - water.y) / water.h, 0.8, 0.98);
    this.updateDecorHud();
  }

  confirmDecor() {
    if (!this.ghost || this.ghost.valid === false) return;
    const tank = tankById(this.state, this.detailTankId);
    if (!tank) return;
    let res;
    if (this.ghost.source === 'tray') {
      res = placeDecorInTank(this.state, this.ghost.trayUid, tank.id, this.ghost.x, this.ghost.y);
    } else {
      const moved = moveDecor(this.state, tank.id, this.ghost.index, this.ghost.x, this.ghost.y);
      res = moved ? { ok: true, message: 'Decoration repositioned.' } : { ok: false, message: 'Could not move that decoration.' };
    }
    if (res.ok) {
      this.ghost = null;
      this.sfx('place');
      this.toast(res.message, 'good');
      this.updateWallet();
      this.renderTray();
      this.renderDetail();
    } else {
      this.toast(res.message, 'bad');
      this.sfx('error');
    }
  }

  scrub() {
    const now = performance.now();
    if (now - this.lastScrub < 38) return;
    this.lastScrub = now;
    const tank = tankById(this.state, this.detailTankId);
    if (!tank) return;
    const res = cleanTank(this.state, tank.id, 2.6);
    if (res.complete) {
      this.sfx('clean');
      this.toast(`${tank.name} is spotless. The residents approve.`, 'good');
    }
    this.refreshDetailDynamic();
  }

  // ------------------------------------------------------------- result helper
  handleResult(res, sfx = 'click') {
    if (!res) return false;
    if (res.message) this.toast(res.message, res.ok ? 'good' : 'bad');
    if (!res.ok) { this.sfx('error'); return false; }
    this.sfx(sfx);
    this.updateWallet();
    this.updateFoods();
    this.renderTray();
    if (this.activeModal === 'shop') this.renderShop();
    if (this.detailOpen) this.renderDetail();
    return true;
  }

  collect(drop, clientX, clientY) {
    if (!drop) return;
    const res = collectDrop(this.state, drop.id);
    if (!res.ok) return;
    this.sfx('coin');
    this.flashWallet();
    this.updateWallet();
    this.floatMoney(`+${formatMoney(res.value)} VNĐ`, clientX, clientY);
    if (this.detailOpen) this.renderDetail();
  }

  // ----------------------------------------------------------------- events
  bindEvents() {
    $('foodItems').addEventListener('click', (e) => {
      const btn = e.target.closest('.food-btn');
      if (btn) this.selectFood(btn.dataset.food);
    });

    $('trayItems').addEventListener('click', (e) => {
      if (this.suppressClick) return;
      const remove = e.target.closest('[data-remove]');
      if (remove) {
        e.stopPropagation();
        const res = sellTrayItem(this.state, remove.dataset.remove);
        if (res.ok) {
          this.toast(res.message, 'good');
          this.sfx('buy');
          this.updateWallet();
          this.renderTray();
          if (this.detailOpen) this.renderDetail();
        }
        return;
      }
      const slot = e.target.closest('.tray-slot[data-uid]');
      if (slot) this.toggleTray(slot.dataset.uid);
    });

    $('trayItems').addEventListener('pointerdown', (e) => this.startTrayDrag(e));
    window.addEventListener('pointermove', (e) => this.moveTrayDrag(e));
    window.addEventListener('pointerup', (e) => this.endTrayDrag(e));
    window.addEventListener('pointercancel', () => this.cancelTrayDrag());

    $('shopBtn').addEventListener('click', () => this.openShop());
    $('helpBtn').addEventListener('click', () => this.openHelp());
    $('soundBtn').addEventListener('click', () => {
      this.state.sound = !this.state.sound;
      this.updateSoundButton();
      this.ensureAudio();
      if (this.state.sound) this.sfx('click');
      saveGame(this.state);
    });

    document.querySelectorAll('[data-close]').forEach(el => {
      el.addEventListener('click', () => {
        const name = el.dataset.close;
        if (name === 'detail') this.closeDetail();
        else this.closeModal(name);
      });
    });

    $('shopTabs').addEventListener('click', (e) => {
      const b = e.target.closest('button[data-tab]');
      if (!b) return;
      this.shopTab = b.dataset.tab;
      this.renderShop();
    });
    $('fishFilters').addEventListener('click', (e) => {
      const b = e.target.closest('button[data-filter]');
      if (!b) return;
      this.shopFilter = b.dataset.filter;
      this.renderShop();
    });
    $('shopGrid').addEventListener('click', (e) => {
      const fish = e.target.closest('[data-buy-fish]');
      if (fish) {
        const res = buyFish(this.state, fish.dataset.buyFish);
        this.handleResult(res, 'buy');
        return;
      }
      const food = e.target.closest('[data-buy-food]');
      if (food) {
        const res = buyFood(this.state, food.dataset.buyFood);
        this.handleResult(res, 'buy');
        return;
      }
      const decor = e.target.closest('[data-buy-decor]');
      if (decor) {
        const res = buyDecor(this.state, decor.dataset.buyDecor);
        this.handleResult(res, 'buy');
      }
    });

    // Scene
    this.sceneCanvas.addEventListener('pointermove', (e) => {
      const p = this.localPoint(this.sceneCanvas, e);
      this.renderer.mouse = p;
      const hit = this.renderer.tankAt(p.x, p.y);
      this.renderer.hoverTank = hit?.id || null;
      const drop = this.renderer.dropAt(p.x, p.y);
      this.sceneCanvas.style.cursor = drop ? 'pointer' : hit ? 'pointer' : 'default';
    });
    this.sceneCanvas.addEventListener('pointerleave', () => {
      this.renderer.hoverTank = null;
      this.sceneCanvas.style.cursor = 'default';
    });
    this.sceneCanvas.addEventListener('click', (e) => this.onSceneClick(e));

    // Detail
    this.detailCanvas.addEventListener('pointermove', (e) => this.onDetailMove(e));
    this.detailCanvas.addEventListener('pointerdown', (e) => this.onDetailDown(e));
    this.detailCanvas.addEventListener('pointerup', () => { this.scrubbing = false; });
    this.detailCanvas.addEventListener('pointercancel', () => { this.scrubbing = false; });
    this.detailCanvas.addEventListener('pointerleave', () => { this.scrubbing = false; });
    $('detailSideBody').addEventListener('click', (e) => this.onDetailSideClick(e));
    $('cleanDone').addEventListener('click', () => {
      this.detailMode = null;
      this.scrubbing = false;
      this.renderDetail();
    });
    $('decorCancel').addEventListener('click', () => {
      this.ghost = null;
      this.updateDecorHud();
      this.renderDetail();
    });
    $('decorConfirm').addEventListener('click', () => this.confirmDecor());

    $('newGameBtn').addEventListener('click', () => {
      if (window.confirm('Start a new aquarium? Current progress will be lost.')) {
        resetGame();
        saveGame(this.state);
        location.reload();
      }
    });

    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        if (this.detailOpen) {
          if (this.detailMode) {
            this.detailMode = null;
            this.ghost = null;
            this.renderDetail();
          } else this.closeDetail();
        } else if (this.activeModal) {
          this.closeModal();
        } else if (this.selectedTray) {
          this.selectedTray = null;
          this.renderTray();
        }
      }
      if (e.key.toLowerCase() === 'b' && !this.detailOpen) this.openShop();
      if (e.key.toLowerCase() === 'h' && !this.detailOpen) this.openHelp();
    });

    window.addEventListener('resize', () => {
      this.renderer.resize();
      if (this.detailOpen) {
        this.detailView.resize();
        this.renderDetail();
      }
    });
  }

  localPoint(canvas, e) {
    const r = canvas.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  onSceneClick(e) {
    if (this.suppressClick) return;
    const p = this.localPoint(this.sceneCanvas, e);
    const drop = this.renderer.dropAt(p.x, p.y);
    if (drop) {
      this.collect(drop, e.clientX, e.clientY);
      return;
    }
    const hit = this.renderer.tankAt(p.x, p.y);
    if (!hit) {
      if (this.selectedTray) {
        this.selectedTray = null;
        this.syncRendererSelection();
        this.renderTray();
      }
      return;
    }
    if (this.selectedTray) {
      const item = this.state.tray.find(i => i.uid === this.selectedTray);
      if (!item) { this.selectedTray = null; return; }
      if (item.kind === 'fish') {
        const res = placeTrayFish(this.state, item.uid, hit.id);
        if (res.ok) {
          this.selectedTray = null;
          this.handleResult(res, 'place');
        } else {
          this.handleResult(res);
        }
      } else {
        const water = hit.water;
        const nx = clamp((p.x - water.x) / water.w, 0.1, 0.9);
        const ny = clamp((p.y - water.y) / water.h, 0.82, 0.97);
        this.openTank(hit.id, { decorTrayUid: item.uid, nx, ny });
      }
      return;
    }
    this.openTank(hit.id);
  }

  onDetailMove(e) {
    const p = this.localPoint(this.detailCanvas, e);
    this.pointer = p;
    if (this.detailMode === 'decor' && this.ghost) this.updateGhostFromPointer(p.x, p.y);
    if (this.detailMode === 'clean' && this.scrubbing) this.scrub();
  }

  onDetailDown(e) {
    const p = this.localPoint(this.detailCanvas, e);
    this.pointer = p;
    this.detailCanvas.setPointerCapture?.(e.pointerId);
    if (this.detailMode === 'clean') {
      if (this.detailView.inWater(p.x, p.y)) {
        this.scrubbing = true;
        this.scrub();
      }
      return;
    }
    if (this.detailMode === 'decor') {
      if (this.ghost) {
        this.updateGhostFromPointer(p.x, p.y);
      } else {
        const d = this.detailView.decorAt(p.x, p.y);
        if (d) this.startDecorExisting(d.index);
      }
      return;
    }
    const drop = this.detailView.dropAt(p.x, p.y);
    if (drop) this.collect(drop, e.clientX, e.clientY);
  }

  onDetailSideClick(e) {
    const sell = e.target.closest('[data-sell]');
    if (sell) {
      const res = sellFish(this.state, this.detailTankId, sell.dataset.sell);
      if (res.ok) {
        this.selectedFish = this.selectedFish.filter(id => id !== sell.dataset.sell);
        this.toast(res.message, 'good');
        this.sfx('buy');
        this.updateWallet();
        this.renderDetail();
      } else {
        this.toast(res.message, 'bad');
        this.sfx('error');
      }
      return;
    }
    const action = e.target.closest('[data-action]');
    if (action) {
      const kind = action.dataset.action;
      if (kind === 'feed') {
        const res = feedTank(this.state, this.detailTankId, this.state.selectedFood);
        if (res.ok) {
          this.toast(res.message, 'good');
          this.sfx('feed');
          this.updateFoods();
          this.renderDetail();
        } else {
          this.toast(res.message, 'bad');
          this.sfx('error');
        }
      } else if (kind === 'clean') {
        this.enterMode('clean');
      } else if (kind === 'inspect') {
        this.enterMode('inspect');
      } else if (kind === 'decor') {
        this.enterMode('decor');
      }
      return;
    }
    const quickFood = e.target.closest('.food-quick [data-food]');
    if (quickFood) {
      this.selectFood(quickFood.dataset.food);
      return;
    }
    const trayDecor = e.target.closest('[data-decor-tray]');
    if (trayDecor) {
      this.startDecorFromTray(trayDecor.dataset.decorTray);
      return;
    }
    const existing = e.target.closest('[data-decor-existing]');
    if (existing) {
      this.startDecorExisting(Number(existing.dataset.decorExisting));
      return;
    }
    const remove = e.target.closest('[data-decor-remove]');
    if (remove) {
      const res = removeDecor(this.state, this.detailTankId, Number(remove.dataset.decorRemove));
      if (res.ok) {
        this.toast(res.message, 'good');
        this.sfx('buy');
        this.updateWallet();
        this.renderDetail();
      }
      return;
    }
    const breed = e.target.closest('[data-breed]');
    if (breed) {
      const res = breedPair(this.state, this.detailTankId, this.selectedFish[0], this.selectedFish[1]);
      if (res.ok) {
        this.selectedFish = [];
        this.toast(res.message, 'good');
        this.sfx('place');
        this.updateWallet();
        this.renderDetail();
      } else {
        this.toast(res.message, 'bad');
        this.sfx('error');
      }
      return;
    }
    const fish = e.target.closest('[data-fish]');
    if (fish) {
      const id = fish.dataset.fish;
      if (this.selectedFish.includes(id)) {
        this.selectedFish = this.selectedFish.filter(x => x !== id);
      } else {
        this.selectedFish.push(id);
        if (this.selectedFish.length > 2) this.selectedFish.shift();
      }
      this.sfx('click');
      this.renderDetail();
    }
  }

  // ------------------------------------------------------------- tray dragging
  startTrayDrag(e) {
    if (e.target.closest('[data-remove]')) return;
    const slot = e.target.closest('.tray-slot[data-uid]');
    if (!slot) return;
    const item = this.state.tray.find(i => i.uid === slot.dataset.uid);
    if (!item) return;
    this.drag = {
      uid: item.uid, item, startX: e.clientX, startY: e.clientY,
      active: false, slot
    };
    if (slot.setPointerCapture) {
      try { slot.setPointerCapture(e.pointerId); } catch (err) { /* ignore */ }
    }
  }

  moveTrayDrag(e) {
    const drag = this.drag;
    if (!drag) return;
    const dist = Math.hypot(e.clientX - drag.startX, e.clientY - drag.startY);
    if (!drag.active && dist > 7) {
      drag.active = true;
      this.selectedTray = drag.uid;
      this.syncRendererSelection();
      this.renderTray();
      const ghost = $('dragGhost');
      const item = drag.item;
      const src = item.kind === 'fish' ? fishThumb(item.speciesId) : decorThumb(item.decorType);
      ghost.innerHTML = `<img src="${src}" alt="">`;
      ghost.hidden = false;
      drag.slot?.classList.add('dragging');
      this.sfx('click');
    }
    if (!drag.active) return;
    const ghost = $('dragGhost');
    ghost.style.left = `${e.clientX}px`;
    ghost.style.top = `${e.clientY}px`;
    const r = this.sceneCanvas.getBoundingClientRect();
    const hit = this.renderer.tankAt(e.clientX - r.left, e.clientY - r.top);
    this.renderer.hoverTank = hit?.id || null;
  }

  endTrayDrag(e) {
    const drag = this.drag;
    if (!drag) return;
    this.drag = null;
    if (!drag.active) return;
    $('dragGhost').hidden = true;
    drag.slot?.classList.remove('dragging');
    this.suppressClick = true;
    setTimeout(() => { this.suppressClick = false; }, 80);

    const r = this.sceneCanvas.getBoundingClientRect();
    const x = e.clientX - r.left, y = e.clientY - r.top;
    const hit = this.renderer.tankAt(x, y);
    if (!hit) {
      this.toast('Drop the item onto a tank to place it.', 'bad');
      this.sfx('error');
      return;
    }
    const item = this.state.tray.find(i => i.uid === drag.uid);
    if (!item) return;
    if (item.kind === 'fish') {
      const res = placeTrayFish(this.state, item.uid, hit.id);
      if (res.ok) {
        this.selectedTray = null;
        this.handleResult(res, 'place');
      } else {
        this.handleResult(res);
      }
    } else {
      const water = hit.water;
      this.openTank(hit.id, {
        decorTrayUid: item.uid,
        nx: clamp((x - water.x) / water.w, 0.1, 0.9),
        ny: clamp((y - water.y) / water.h, 0.82, 0.97)
      });
    }
  }

  cancelTrayDrag() {
    if (!this.drag) return;
    this.drag = null;
    $('dragGhost').hidden = true;
    document.querySelectorAll('.tray-slot.dragging').forEach(el => el.classList.remove('dragging'));
  }

  // -------------------------------------------------------------------- frame
  draw(time) {
    if (!this.detailOpen) return;
    const tank = tankById(this.state, this.detailTankId);
    if (!tank) return;
    this.detailView.draw(tank, time, {
      mode: this.detailMode,
      pointer: this.pointer,
      ghost: this.ghost,
      selectedDecor: this.ghost?.source === 'existing' ? this.ghost.index : null
    });
  }

  tick(now) {
    if (now - this.lastTick > 260) {
      this.lastTick = now;
      this.updateClock();
      if (this.detailOpen) {
        this.refreshDetailDynamic();
        // keep HUD numbers live while the side panel sits still
        const tank = tankById(this.state, this.detailTankId);
        if (tank) {
          const pct = Math.round(tank.cleanliness);
          const bar = $('cleanBar');
          if (bar) bar.style.backgroundSize = `${pct}% 100%`;
          const cp = $('cleanPct');
          if (cp) cp.textContent = `${pct}%`;
        }
      }
      this.drainEvents();
    }
  }

  drainEvents() {
    const events = this.state.events.splice(0, this.state.events.length);
    for (const ev of events) {
      if (ev.type === 'hatch') {
        const tank = tankById(this.state, ev.tankId);
        const sp = SPECIES[ev.speciesId];
        this.toast(`${ev.names.join(' & ')} hatched in ${tank?.name || 'the tank'} — ${sp?.name || 'fry'} fry!`, 'good');
        this.sfx('place');
        if (this.detailOpen && this.detailTankId === ev.tankId) this.renderDetail();
      } else if (ev.type === 'day') {
        this.toast(`Ngày ${ev.day} begins. The shop lights are warm and the filters are humming.`);
      } else if (ev.type === 'clean') {
        // handled directly by the scrub interaction
      }
    }
  }
}

import { createState, loadGame, saveGame, update } from './game.js';
import { SceneRenderer } from './render.js';
import { UI } from './ui.js';

const canvas = document.getElementById('scene');
const state = loadGame() || createState();
const renderer = new SceneRenderer(canvas, state);
const ui = new UI(state, renderer);

let last = performance.now();
let lastSave = last;

function frame(now) {
  const dt = (now - last) / 1000;
  last = now;
  update(state, dt);
  ui.tick(now);

  const t = now / 1000;
  if (!ui.detailOpen) renderer.draw(t);
  ui.draw(t);

  if (now - lastSave > 7000) {
    saveGame(state);
    lastSave = now;
  }
  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);

document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    saveGame(state);
  } else {
    last = performance.now();
  }
});
window.addEventListener('beforeunload', () => saveGame(state));

// A tiny public handle is useful for debugging and automated smoke checks.
window.__THUYCUNG__ = { state, renderer, ui };

