function drawHump(ctx, species) {
  if (species.body !== 'round') return;
  const c = species.colors;
  const p = BODY.round;
  for (let x = p.x1 - 42; x <= p.x1 - 1; x++) {
    const t = (x - (p.x1 - 42)) / 41;
    const h = Math.pow(Math.sin(t * Math.PI * 0.92), 0.75) * 17;
    for (let y = Math.round(CY - 15 - h); y < Math.round(CY - 12); y++) {
      const v = (y - (CY - 15 - h)) / Math.max(1, h + 3);
      let col = mix(c.back, c.base, 0.2 + v * 0.7);
      if (v < 0.22) col = mix(col, c.fin2, 0.18);
      if (v > 0.78) col = mix(col, c.belly, 0.2);
      ctx.fillStyle = col;
      ctx.fillRect(x, y, 1, 1);
    }
  }
  // glossy crown highlight
  ctx.fillStyle = alpha(c.fin2, 0.5);
  ctx.fillRect(p.x1 - 30, CY - 28, 7, 1);
  ctx.fillRect(p.x1 - 28, CY - 27, 3, 1);
  ctx.fillStyle = alpha(c.accent, 0.4);
  ctx.fillRect(p.x1 - 42, CY - 16, 3, 1);
}

