44: const BODY = {
45:   gar: { x0: 40, x1: 108, maxH: 10, tailX: 12, tailSpread: 12, fork: 0, tailLen: 'round' },
46:   elongated: { x0: 38, x1: 112, maxH: 11, tailX: 10, tailSpread: 12, fork: 0, tailLen: 'round' },
47:   catfish: { x0: 36, x1: 112, maxH: 15, tailX: 4, tailSpread: 17, fork: 0.55, tailLen: 'fork' },
48:   round: { x0: 34, x1: 112, maxH: 21, tailX: 12, tailSpread: 13, fork: 0, tailLen: 'round' },
49:   betta: { x0: 46, x1: 108, maxH: 14, tailX: 2, tailSpread: 31, fork: 0, tailLen: 'betta' },
50:   cory: { x0: 38, x1: 108, maxH: 12, tailX: 10, tailSpread: 12, fork: 0.5, tailLen: 'fork' },
51:   paradise: { x0: 38, x1: 110, maxH: 13, tailX: 10, tailSpread: 14, fork: 0.45, tailLen: 'fork' }
52: };
