54: function profileH(species, body, t) {
55:   const p = BODY[body] || BODY.elongated;
56:   let h = Math.pow(Math.sin(Math.PI * Math.min(1, Math.max(0, t))), 0.58) * (1 - 0.1 * t) * p.maxH;
57:   if (species.id === 'gar') h *= 0.82 + 0.18 * Math.pow(1 - t, 2);
58:   if (species.body === 'cory') h *= 0.95;
59:   return Math.max(1, h);
60: }
61: 
62: function bodyPath(species) {
63:   const p = BODY[species.body] || BODY.elongated;
64:   const top = [], bottom = [];
65:   for (let x = p.x0; x <= p.x1; x++) {
66:     const t = (x - p.x0) / (p.x1 - p.x0);
67:     const h = profileH(species, species.body, t);
68:     top.push([x, CY - h]);
69:     bottom.push([x, CY + h]);
70:   }
71:   return { top, bottom, p };
72: }
