74: function drawBody(ctx, species, frame) {
75:   const p = BODY[species.body] || BODY.elongated;
76:   const c = species.colors;
77:   for (let x = p.x0; x <= p.x1; x++) {
78:     const t = (x - p.x0) / (p.x1 - p.x0);
79:     const h = profileH(species, species.body, t);
80:     const bellyScale = species.body === 'cory' ? 0.68 : 1;
81:     for (let y = Math.round(CY - h); y <= Math.round(CY + h * bellyScale); y++) {
82:       const v = (y - CY) / h;
83:       let col;
84:       if (v < 0) col = mix(c.back, c.base, Math.min(1, (v + 1) * 1.15));
85:       else col = mix(c.base, c.belly, Math.min(1, v * 1.2));
86:       // subtle lateral sheen
87:       if (v > -0.15 && v < 0.1) col = mix(col, c.fin2 || c.belly, 0.1 + 0.08 * Math.sin(t * 9 + frame));
88:       ctx.fillStyle = col;
89:       ctx.fillRect(x, y, 1, 1);
90:     }
91:     // dark dorsal edge
92:     ctx.fillStyle = alpha(c.accent, 0.55);
93:     ctx.fillRect(x, Math.round(CY - h), 1, 1);
94:     if (species.body !== 'cory') ctx.fillRect(x, Math.round(CY + h), 1, 1);
95:   }
96:   // gar's long armoured snout
97:   if (species.id === 'gar') {
98:     for (let x = 105; x <= 124; x++) {
99:       const t = (x - 105) / 19;
100:       const h = 4.2 - t * 2.2;
101:       for (let y = Math.round(CY - h); y <= Math.round(CY + h); y++) {
102:         const v = (y - CY) / h;
103:         ctx.fillStyle = v < -0.2 ? mix(c.back, c.base, 0.6) : mix(c.base, c.belly, 0.4 + v * 0.4);
104:         ctx.fillRect(x, y, 1, 1);
105:       }
106:     }
107:     ctx.fillStyle = alpha(c.accent, 0.85);
108:     ctx.fillRect(105, CY - 4, 19, 1);
109:     ctx.fillRect(105, CY + 3, 19, 1);
110:     // teeth glints
111:     for (let x = 108; x < 122; x += 3) {
112:       ctx.fillStyle = '#f3ead2';
113:       ctx.fillRect(x, CY + 1, 1, 1);
114:     }
115:   }
116: }
