118: function drawTail(ctx, species, frame) {
119:   const p = BODY[species.body] || BODY.elongated;
120:   const c = species.colors;
121:   const phase = (frame / FRAMES) * Math.PI * 2;
122:   const sway = Math.sin(phase) * (species.body === 'betta' ? 5 : 3.5);
123:   const baseX = p.x0 + 2;
124:   const tipX = p.tailX;
125:   const finColor = c.fin;
126:   const finLight = c.fin2 || mix(c.fin, '#ffffff', 0.28);
127: 
128:   if (p.tailLen === 'betta' && species.finStyle === 'halfmoon') {
129:     // Giant 180° halfmoon skirt, scanned by y so the outer edge is a true arc.
130:     const rx = 45, ry = 32;
131:     for (let y = -ry; y <= ry; y++) {
132:       const v = y / ry;
133:       const arc = Math.sqrt(Math.max(0, 1 - v * v));
134:       const xTip = Math.round(baseX - rx * arc + sway * 0.4 * v);
135:       const cy = CY;
136:       for (let x = xTip; x <= baseX; x++) {
137:         const t = (x - xTip) / Math.max(1, baseX - xTip);
138:         let col = mix(c.fin, c.back, Math.pow(Math.abs(v), 2.4) * 0.5);
139:         col = mix(col, finLight, Math.pow(t, 2.6) * 0.5 + (1 - arc) * 0.18);
140:         if (t > 0.9) col = mix(col, shade(c.fin, -0.22), 0.32);
141:         ctx.fillStyle = col;
142:         ctx.fillRect(x, cy + y, 1, 1);
143:       }
144:     }
145:     // radial fin rays
146:     ctx.strokeStyle = alpha(finLight, 0.55);
147:     ctx.lineWidth = 0.7;
148:     for (let i = -10; i <= 10; i++) {
149:       const a = (i / 10) * Math.PI * 0.5;
150:       ctx.beginPath();
151:       ctx.moveTo(baseX, CY + sway * 0.2);
152:       ctx.lineTo(baseX - rx * Math.cos(a), CY + ry * Math.sin(a));
153:       ctx.stroke();
154:     }
155:     ctx.strokeStyle = alpha(finLight, 0.85);
156:     ctx.lineWidth = 1;
157:     for (let i = -12; i <= 12; i++) {
158:       const a = (i / 12) * Math.PI * 0.5;
159:       const edge = 0.92 + Math.sin(i * 2.1) * 0.012;
160:       ctx.beginPath();
161:       ctx.moveTo(baseX - rx * Math.cos(a) * edge, CY + ry * Math.sin(a) * edge);
162:       ctx.lineTo(baseX - rx * Math.cos(a) * edge + 1, CY + ry * Math.sin(a) * edge);
163:       ctx.stroke();
164:     }
165:     return;
166:   }
167: 
168:   if (p.tailLen === 'betta') {
169:     // Crown tail — membrane plus long needle rays.
170:     const rx = 35, ry = 28;
171:     for (let y = -ry; y <= ry; y++) {
172:       const v = y / ry;
173:       const arc = Math.sqrt(Math.max(0, 1 - v * v));
174:       const xTip = Math.round(baseX - rx * arc * 0.72 + sway * 0.4 * v);
175:       for (let x = xTip; x <= baseX; x++) {
176:         const t = (x - xTip) / Math.max(1, baseX - xTip);
177:         let col = mix(c.fin, c.back, Math.pow(Math.abs(v), 3) * 0.55);
178:         col = mix(col, finLight, Math.pow(t, 3) * 0.45);
179:         ctx.fillStyle = col;
180:         ctx.fillRect(x, CY + y, 1, 1);
181:       }
182:     }
183:     ctx.strokeStyle = c.fin2 || finLight;
184:     ctx.lineWidth = 1;
185:     for (let i = -9; i <= 9; i++) {
186:       const a = (i / 9) * Math.PI * 0.5;
187:       ctx.beginPath();
188:       ctx.moveTo(baseX, CY + sway * 0.2);
189:       ctx.lineTo(baseX - rx * 1.18 * Math.cos(a), CY + ry * 1.18 * Math.sin(a));
190:       ctx.stroke();
191:     }
192:     return;
193:   }
194: 
195:   const fork = p.fork || 0;
196:   for (let x = tipX; x <= baseX; x++) {
197:     const t = (x - tipX) / (baseX - tipX);
198:     const half = 2 + (p.tailSpread - 2) * Math.pow(1 - t, 0.72);
199:     const cy = CY + sway * 0.75 * (1 - t);
200:     const notch = fork * (0.42 - Math.min(t, 0.42)) * half * 1.15;
201:     const topY = Math.round(cy - half), botY = Math.round(cy + half);
202:     for (let y = topY; y <= botY; y++) {
203:       if (notch > 0 && Math.abs(y - cy) < notch) continue;
204:       const v = Math.abs((y - cy) / half);
205:       let col = mix(finColor, c.back, Math.pow(v, 2.2) * 0.5);
206:       if (v < 0.28) col = mix(col, finLight, 0.3);
207:       ctx.fillStyle = col;
208:       ctx.fillRect(x, y, 1, 1);
209:     }
210:   }
211:   // crisp outer edge
212:   ctx.fillStyle = alpha(finLight, 0.5);
213:   for (let x = tipX; x <= baseX; x++) {
214:     const t = (x - tipX) / (baseX - tipX);
215:     const half = 2 + (p.tailSpread - 2) * Math.pow(1 - t, 0.72);
216:     const cy = CY + sway * 0.75 * (1 - t);
217:     if (fork > 0 && (0.42 - t) > 0 && Math.abs(half - 0.0) > 0) {
218:       // fork edges only
219:       if (t < 0.4) continue;
220:     }
221:     ctx.fillRect(x, Math.round(cy - half), 1, 1);
222:     ctx.fillRect(x, Math.round(cy + half), 1, 1);
223:   }
224:   // translucent fin rays
225:   ctx.strokeStyle = alpha(finLight, 0.42);
226:   ctx.lineWidth = 0.65;
227:   for (let i = -4; i <= 4; i++) {
228:     const v = i / 4;
229:     ctx.beginPath();
230:     ctx.moveTo(baseX - 1, CY + sway * 0.2);
231:     ctx.quadraticCurveTo(
232:       tipX + (baseX - tipX) * 0.45,
233:       CY + sway * 0.5 + v * p.tailSpread * 0.45,
234:       tipX + 1,
235:       CY + sway + v * p.tailSpread * 0.92
236:     );
237:     ctx.stroke();
238:   }
239: }
