372: function drawPattern(ctx, species, frame) {
373:   const c = species.colors;
374:   const p = BODY[species.body] || BODY.elongated;
375:   const rnd = prng(hashString(species.id) + 17);
376:   const inBody = (x, y) => {
377:     if (x < p.x0 || x > p.x1) return false;
378:     const t = (x - p.x0) / (p.x1 - p.x0);
379:     const h = profileH(species, species.body, t);
380:     return y > CY - h + 1 && y < CY + h * 0.96 - 1;
381:   };
382:   const dot = (x, y, r, col) => {
383:     for (let dx = -r; dx <= r; dx++) {
384:       for (let dy = -r; dy <= r; dy++) {
385:         if (dx * dx + dy * dy <= r * r + 0.5 && inBody(Math.round(x + dx), Math.round(y + dy))) {
386:           ctx.fillStyle = col;
387:           ctx.fillRect(Math.round(x + dx), Math.round(y + dy), 1, 1);
388:         }
389:       }
390:     }
391:   };
392: 
393:   switch (species.pattern) {
394:     case 'leopard': {
395:       for (let i = 0; i < 22; i++) {
396:         const x = p.x0 + 8 + rnd() * (p.x1 - p.x0 - 12);
397:         const y = CY - 6 + rnd() * 11;
398:         dot(x, y, rnd() < 0.4 ? 2 : 1, alpha(c.accent, 0.78));
399:       }
400:       for (let i = 0; i < 12; i++) {
401:         const x = p.x0 + 8 + rnd() * (p.x1 - p.x0 - 12);
402:         const y = CY - 5 + rnd() * 9;
403:         dot(x, y, 0, alpha(mix(c.belly, '#ffffff', 0.4), 0.5));
404:       }
405:       break;
406:     }
407:     case 'blotch': {
408:       for (let i = 0; i < 13; i++) {
409:         const x = p.x0 + 6 + rnd() * (p.x1 - p.x0 - 8);
410:         const y = CY - 7 + rnd() * 12;
411:         const r = rnd() < 0.5 ? 2 : 3;
412:         dot(x, y, r, alpha(c.accent, 0.6 + rnd() * 0.2));
413:       }
414:       // electric edge along the back
415:       for (let x = p.x0 + 10; x < p.x1 - 8; x += 2) {
416:         const t = (x - p.x0) / (p.x1 - p.x0);
417:         const h = profileH(species, species.body, t);
418:         ctx.fillStyle = alpha(c.fin2 || c.belly, 0.3);
419:         if (rnd() < 0.7) ctx.fillRect(x, Math.round(CY - h + 1), 1, 1);
420:       }
421:       break;
422:     }
423:     case 'scales': {
424:       for (let x = p.x0 + 6; x < p.x1 - 2; x += 4) {
425:         const t = (x - p.x0) / (p.x1 - p.x0);
426:         const h = profileH(species, species.body, t);
427:         for (let y = Math.round(CY - h + 3); y < Math.round(CY + h - 1); y += 4) {
428:           ctx.fillStyle = alpha(mix(c.belly, '#ffffff', 0.3), 0.36);
429:           ctx.fillRect(x, y, 2, 1);
430:           ctx.fillStyle = alpha(c.accent, 0.22);
431:           ctx.fillRect(x + 3, y + 1, 1, 1);
432:         }
433:       }
434:       for (let x = p.x0 + 8; x < p.x1 - 10; x += 2) {
435:         ctx.fillStyle = alpha(c.fin2 || '#ffffff', 0.1);
436:         ctx.fillRect(x, CY - 2, 1, 3);
437:       }
438:       break;
439:     }
440:     case 'speckle': {
441:       for (let i = 0; i < 28; i++) {
442:         const x = p.x0 + 5 + rnd() * (p.x1 - p.x0 - 8);
443:         const y = CY - 9 + rnd() * 17;
444:         dot(x, y, 0, alpha(mix(c.belly, '#ffffff', 0.5), 0.4 + rnd() * 0.3));
445:       }
446:       break;
447:     }
448:     case 'flowerhorn': {
449:       for (let i = 0; i < 11; i++) {
450:         const x = p.x0 + 8 + rnd() * (p.x1 - p.x0 - 14);
451:         const y = CY - 9 + rnd() * 16;
452:         dot(x, y, rnd() < 0.5 ? 2 : 3, alpha(c.accent, 0.55));
453:       }
454:       for (let x = 70; x < 98; x++) {
455:         for (let y = CY - 11; y < CY + 6; y++) {
456:           if (inBody(x, y) && rnd() < 0.5) {
457:             ctx.fillStyle = alpha(c.red, 0.35 + 0.2 * Math.sin(x * 0.3 + y));
458:             ctx.fillRect(x, y, 1, 1);
459:           }
460:         }
461:       }
462:       for (let i = 0; i < 18; i++) {
463:         const x = p.x0 + 8 + rnd() * (p.x1 - p.x0 - 12);
464:         const y = CY - 8 + rnd() * 15;
465:         dot(x, y, 0, alpha(c.fin2, 0.45));
466:       }
467:       break;
468:     }
469:     case 'panda': {
470:       // black eye mask
471:       for (let x = 92; x < 106; x++) {
472:         for (let y = CY - 8; y < CY + 2; y++) {
473:           if (inBody(x, y) && (y < CY - 2 || rnd() < 0.5)) {
474:             ctx.fillStyle = c.accent;
475:             ctx.fillRect(x, y, 1, 1);
476:           }
477:         }
478:       }
479:       // back patch
480:       for (let x = 62; x < 80; x++) {
481:         for (let y = CY - 9; y < CY - 1; y++) {
482:           if (inBody(x, y) && rnd() < 0.85) {
483:             ctx.fillStyle = c.accent;
484:             ctx.fillRect(x, y, 1, 1);
