261:     const sp = SPECIES[fish.speciesId];
262:     if (!sp) continue;
263:     const p = mapFishPos(water, fish);
264:     const depth = 0.84 + fish.y * 0.22;
265:     const width = water.w * (VIS[fish.speciesId] || 0.3) * depth * (detail ? (tank.kind === 'large' ? 1 : 1.08) : 1);
266:     drawFishSprite(ctx, fish.speciesId, time + fish.id.length * 0.13, p.x, p.y, width, fish.dir, fish.growth);
267:     if (fish.feedFlash > 0) {
268:       ctx.fillStyle = `rgba(255,235,170,${fish.feedFlash * 0.05})`;
269:       ctx.beginPath();
270:       ctx.arc(p.x, p.y, width * 0.16, 0, TAU);
271:       ctx.fill();
272:     }
273:   }
274: 
275:   // feed particles
276:   for (const p of tank.feedParticles) {
277:     const px = water.x + p.x * water.w;
278:     const py = water.y + p.y * water.h;
279:     drawFoodParticle(ctx, p.foodId, px, py, Math.max(0.7, water.w / 500) * p.size, p.color);
280:     ctx.fillStyle = `rgba(255,243,196,${clamp(p.life / 6, 0, 1) * 0.1})`;
281:     ctx.fillRect(px - 2, py - 2, 4, 4);
282:   }
283: 
284:   // grime overlay
285:   const dirt = clamp(1 - tank.cleanliness / 100, 0, 1);
286:   if (dirt > 0.01) {
287:     const tex = grimeTexture(tank);
288:     ctx.save();
289:     ctx.globalAlpha = dirt * (opts.cleanMode ? 0.62 : detail ? 0.5 : 0.3);
290:     ctx.drawImage(tex, water.x, water.y, water.w, water.h);
291:     // green water haze
292:     ctx.fillStyle = 'rgba(84,107,50,.1)';
293:     ctx.fillRect(water.x, water.y, water.w, water.h);
294:     ctx.restore();
295:   }
296: 
297:   // glass reflections
298:   ctx.save();
299:   ctx.globalCompositeOperation = 'screen';
300:   const shine = ctx.createLinearGradient(water.x, water.y, water.x + water.w, water.y + water.h);
301:   shine.addColorStop(0, 'rgba(255,255,255,.08)');
302:   shine.addColorStop(0.2, 'rgba(255,255,255,.015)');
303:   shine.addColorStop(0.55, 'rgba(255,255,255,.06)');
304:   shine.addColorStop(0.62, 'rgba(255,255,255,0)');
305:   ctx.fillStyle = shine;
306:   ctx.fillRect(water.x, water.y, water.w, water.h);
307:   // diagonal reflection bar
308:   ctx.fillStyle = 'rgba(222,252,250,.055)';
309:   ctx.beginPath();
310:   ctx.moveTo(water.x + water.w * 0.42, water.y);
311:   ctx.lineTo(water.x + water.w * 0.52, water.y);
312:   ctx.lineTo(water.x + water.w * 0.34, water.y + water.h);
313:   ctx.lineTo(water.x + water.w * 0.25, water.y + water.h);
314:   ctx.closePath();
315:   ctx.fill();
316:   ctx.restore();
317: 
318:   // surface
319:   ctx.strokeStyle = 'rgba(210,255,248,.46)';
320:   ctx.lineWidth = 1;
321:   ctx.beginPath();
322:   for (let i = 0; i <= 18; i++) {
323:     const px = water.x + (water.w / 18) * i;
324:     const py = water.y + 3 + Math.sin(i * 0.7 + time * 2.2) * 1.4;
325:     if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
326:   }
327:   ctx.stroke();
328: 
329:   // money drops
330:   const dropScale = detail ? clamp(water.w / 420, 1.1, 1.7) : clamp(water.w / 520, 0.6, 0.95);
331:   const tankDrops = state.drops.filter(d => d.tankId === tank.id);
332:   for (let i = 0; i < tankDrops.length; i++) {
333:     const d = tankDrops[i];
334:     const dx = water.x + d.x * water.w;
335:     const dy = water.y + (0.12 + d.y * 0.7) * water.h;
336:     drawBanknote(ctx, dx, dy, dropScale, time + i, d.value);
337:     drops.push({ id: d.id, x: dx, y: dy, r: 26 * dropScale, value: d.value });
338:   }
339:   return { drops, decor: decorHit };
340: }
341: 
342: function drawTankFrame(ctx, tank, rect, opts = {}) {
343:   const detail = !!opts.detail;
344:   const small = rect.w < 260;
345:   const frame = detail ? Math.max(6, rect.w * 0.009) : Math.max(4, Math.min(8, rect.w * 0.012));
346:   const plaqueH = opts.plaque ? (small ? 14 : 20) : 0;
347:   const water = {
348:     x: rect.x + frame,
349:     y: rect.y + frame,
350:     w: rect.w - frame * 2,
351:     h: rect.h - frame * 2 - plaqueH
352:   };
353: 
354:   // ambient glow behind the glass
355:   ctx.save();
356:   ctx.shadowColor = 'rgba(68,210,210,.28)';
357:   ctx.shadowBlur = detail ? 40 : 22;
358:   ctx.fillStyle = '#0d1a1d';
359:   roundRect(ctx, rect.x, rect.y, rect.w, rect.h, 5);
360:   ctx.fill();
361:   ctx.restore();
362: 
363:   // cabinet lip / outer frame
364:   const frameGrad = ctx.createLinearGradient(rect.x, rect.y, rect.x, rect.y + rect.h);
365:   frameGrad.addColorStop(0, '#29343a');
366:   frameGrad.addColorStop(0.2, '#151e23');
367:   frameGrad.addColorStop(0.8, '#10171b');
368:   frameGrad.addColorStop(1, '#070c0e');
369:   ctx.fillStyle = frameGrad;
370:   roundRect(ctx, rect.x, rect.y, rect.w, rect.h, 5);
371:   ctx.fill();
372:   ctx.strokeStyle = 'rgba(148,174,178,.22)';
373:   ctx.lineWidth = 1;
374:   ctx.stroke();
375: 
376:   // rubber gasket
377:   ctx.strokeStyle = '#05090b';
378:   ctx.lineWidth = 2;
379:   roundRect(ctx, water.x - 2, water.y - 2, water.w + 4, water.h + 4, 3);
380:   ctx.stroke();
381: 
382:   ctx.save();
383:   roundRect(ctx, water.x, water.y, water.w, water.h, 2);
384:   ctx.clip();
385:   const hits = drawInnerTank(ctx, tank, water, opts.state, opts.time, { detail, cleanMode: opts.cleanMode });
386:   ctx.restore();
387: 
388:   // inner rim highlight
389:   ctx.strokeStyle = 'rgba(218,247,244,.2)';
390:   ctx.lineWidth = 1;
391:   roundRect(ctx, water.x, water.y, water.w, water.h, 2);
392:   ctx.stroke();
393: 
394:   // corner bolts
395:   ctx.fillStyle = '#4f5e63';
396:   const bolt = detail ? 3 : 2;
397:   const corners = [
398:     [rect.x + 4, rect.y + 4], [rect.x + rect.w - 4, rect.y + 4],
399:     [rect.x + 4, rect.y + rect.h - (plaqueH ? plaqueH + 5 : 4)],
400:     [rect.x + rect.w - 4, rect.y + rect.h - (plaqueH ? plaqueH + 5 : 4)]
401:   ];
402:   for (const [cx, cy] of corners) {
403:     ctx.beginPath();
404:     ctx.arc(cx, cy, bolt, 0, TAU);
405:     ctx.fill();
406:   }
407: 
408:   if (plaqueH) {
409:     const py = rect.y + rect.h - plaqueH;
410:     ctx.fillStyle = '#0b1114';
411:     ctx.fillRect(rect.x + frame, py, rect.w - frame * 2, plaqueH - 2);
412:     ctx.fillStyle = 'rgba(231,197,119,.2)';
413:     ctx.fillRect(rect.x + frame, py, rect.w - frame * 2, 1);
414:     const fs = small ? Math.max(6, Math.min(8, rect.w * 0.038)) : Math.max(8, Math.min(11, rect.w * 0.019));
415:     ctx.textAlign = 'left';
416:     ctx.textBaseline = 'middle';
417:     ctx.font = `700 ${fs}px "Courier New", monospace`;
418:     ctx.fillStyle = '#e7c577';
419:     ctx.fillText(`${tank.code} · ${tank.name}`, rect.x + frame + 6, py + plaqueH * 0.5);
420:     ctx.textAlign = 'right';
421:     ctx.font = `600 ${Math.max(5, fs - 1)}px "Courier New", monospace`;
422:     ctx.fillStyle = '#8fa4a7';
423:     ctx.fillText(`${tank.sizeCm}CM · ${tank.fish.length}/${tank.capacity}`, rect.x + rect.w - frame - 6, py + plaqueH * 0.5);
424:     // cleanliness indicator
425:     const dotColor = tank.cleanliness > 65 ? '#69c087' : tank.cleanliness > 35 ? '#e0b44e' : '#d75e4f';
426:     ctx.fillStyle = dotColor;
427:     ctx.beginPath();
428:     ctx.arc(rect.x + frame + 2, py + plaqueH * 0.5, 1.8, 0, TAU);
429:     ctx.fill();
430:   }
431:   return { water, hits };
432: }
433: 
434: // ---------------------------------------------------------------------------
435: // Full-room renderer
436: // ---------------------------------------------------------------------------
437: export class SceneRenderer {
438:   constructor(canvas, state) {
439:     this.canvas = canvas;
440:     this.ctx = canvas.getContext('2d');
441:     this.state = state;
442:     this.dpr = 1;
443:     this.w = 0; this.h = 0;
444:     this.hit = { tanks: [], drops: [] };
445:     this.hoverTank = null;
446:     this.selection = null;
447:     this.mouse = { x: -1, y: -1 };
448:     this.resize();
449:   }
450: 
451:   resize() {
452:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
453:     const w = this.canvas.clientWidth || window.innerWidth;
454:     const h = this.canvas.clientHeight || window.innerHeight;
455:     this.dpr = dpr; this.w = w; this.h = h;
456:     this.canvas.width = Math.round(w * dpr);
457:     this.canvas.height = Math.round(h * dpr);
458:   }
459: 
460:   layout() {
461:     const w = this.w, h = this.h;
462:     const portrait = w < 760 && h > w * 1.02;
463:     let left, right, top, bottom, availW, availH, bigH, smallH, bigGap, smallGap;
464:     if (portrait) {
465:       left = 66; right = 12; top = 76; bottom = Math.max(104, h * 0.12);
466:       availW = w - left - right;
467:       availH = h - top - bottom;
468:       bigGap = 14;
469:       bigH = (availH * 0.44 - bigGap) / 2;
470:       smallH = Math.min(104, (availH - bigH * 2 - bigGap - 50) / 3);
471:       const tanks = [];
472:       tanks.push({ id: 'P1', x: left, y: top, w: availW, h: bigH });
473:       tanks.push({ id: 'P2', x: left, y: top + bigH + bigGap, w: availW, h: bigH });
474:       const sw = (availW - 8) / 2;
475:       const sy = top + bigH * 2 + bigGap + 38;
476:       ['S1', 'S2', 'S3', 'S4', 'S5'].forEach((id, i) => {
477:         const col = i % 2, row = Math.floor(i / 2);
478:         tanks.push({ id, x: left + col * (sw + 8), y: sy + row * (smallH + 7), w: sw, h: smallH });
479:       });
480:       return { w, h, portrait, left, right, top, bottom, availW, availH, bigH, smallH, bigGap, sw, sy, tanks, supply: { x: left + (sw + 8), y: sy + 2 * (smallH + 7), w: sw, h: smallH } };
481:     }
482:     left = Math.max(104, Math.min(158, w * 0.09));
483:     right = Math.max(18, w * 0.018);
484:     top = Math.max(78, h * 0.095);
485:     bottom = Math.max(100, h * 0.13);
486:     availW = w - left - right;
487:     availH = h - top - bottom;
488:     bigGap = Math.max(10, w * 0.012);
489:     const bigW = (availW - bigGap) / 2;
490:     bigH = availH * 0.47;
491:     const sg = Math.max(6, w * 0.008);
492:     const sw = (availW - sg * 4) / 5;
493:     smallH = Math.min(availH * 0.37, sw * 1.18);
494:     const sy = top + bigH + Math.max(42, h * 0.055);
495:     const tanks = [
496:       { id: 'P1', x: left, y: top, w: bigW, h: bigH },
497:       { id: 'P2', x: left + bigW + bigGap, y: top, w: bigW, h: bigH }
498:     ];
499:     ['S1', 'S2', 'S3', 'S4', 'S5'].forEach((id, i) => {
500:       tanks.push({ id, x: left + i * (sw + sg), y: sy, w: sw, h: smallH });
501:     });
502:     return { w, h, portrait, left, right, top, bottom, availW, availH, bigH, smallH, sy, bigGap, tanks, supply: { x: left + (availW - sw) / 2, y: sy + smallH + 18, w: sw, h: 1 } };
503:   }
504: 
505:   draw(time) {
506:     const ctx = this.ctx;
507:     const { w, h } = this;
508:     ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
509:     ctx.clearRect(0, 0, w, h);
510:     const layout = this.layout();
511:     this.layoutData = layout;
512:     this.hit = { tanks: [], drops: [] };
513:     this.drawRoom(ctx, layout, time);
514: 
515:     for (const region of layout.tanks) {
516:       const tank = this.state.tanks.find(t => t.id === region.id);
517:       if (!tank) continue;
518:       this.drawStand(ctx, region, tank, layout, time);
519:     }
520: 
521:     // background rack framing
522:     this.drawRacks(ctx, layout, time);
523: 
524:     for (const region of layout.tanks) {
525:       const tank = this.state.tanks.find(t => t.id === region.id);
526:       if (!tank) continue;
527:       const selected = this.selection;
528:       let compatible = null;
529:       if (selected?.kind === 'fish') {
530:         const sp = SPECIES[selected.speciesId];
531:         compatible = sp.group === (tank.kind === 'large' ? 'predator' : 'small') && tank.fish.length < tank.capacity + 1;
532:       } else if (selected?.kind === 'decor') {
533:         compatible = tank.decor.length < 9;
534:       }
535:       const hovered = this.hoverTank === tank.id;
536:       if (hovered || compatible) this.drawTankAura(ctx, region, compatible, time);
537:       const { water, hits } = drawTankFrame(ctx, tank, region, {
538:         state: this.state, time, plaque: true, detail: false
539:       });
540:       this.hit.tanks.push({ id: tank.id, region, water });
541:       for (const d of hits.drops) this.hit.drops.push({ ...d, tankId: tank.id });
542:       if (hovered) {
543:         ctx.strokeStyle = 'rgba(231,197,119,.85)';
544:         ctx.lineWidth = 1.5;
545:         roundRect(ctx, region.x - 2, region.y - 2, region.w + 4, region.h + 4, 7);
546:         ctx.stroke();
547:       }
548:       if (compatible) {
549:         const pulse = 0.45 + Math.sin(time * 3) * 0.2;
550:         ctx.strokeStyle = `rgba(112,220,170,${pulse + 0.2})`;
551:         ctx.lineWidth = 2;
552:         roundRect(ctx, region.x - 3, region.y - 3, region.w + 6, region.h + 6, 8);
553:         ctx.stroke();
554:         if (layout.portrait || region.w > 260) {
555:           const label = selected.kind === 'fish' ? 'PLACE FISH' : 'PLACE DECOR';
556:           ctx.font = `700 ${layout.portrait ? 7 : 9}px "Courier New", monospace`;
557:           const tw = ctx.measureText(label).width + 12;
558:           const lx = region.x + region.w / 2, ly = region.y + 10;
559:           ctx.fillStyle = 'rgba(10,30,25,.82)';
560:           roundRect(ctx, lx - tw / 2, ly - 8, tw, 15, 3);
561:           ctx.fill();
562:           ctx.fillStyle = '#8fe6bd';
563:           ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
564:           ctx.fillText(label, lx, ly);
565:         }
566:       }
567:     }
568: 
569:     // supply crate fills the sixth nano slot on portrait screens
570:     if (layout.portrait && layout.supply) this.drawSupplyCrate(ctx, layout.supply, time);
571: 
572:     this.drawFloorProps(ctx, layout, time);
573:     this.drawHoverTag(ctx, layout, time);
574:   }
575: 
576:   drawRoom(ctx, layout, time) {
577:     const { w, h, left, top, availW } = layout;
578:     const bg = ctx.createLinearGradient(0, 0, 0, h);
579:     bg.addColorStop(0, '#081116');
580:     bg.addColorStop(0.55, '#0b1a20');
581:     bg.addColorStop(1, '#071013');
582:     ctx.fillStyle = bg;
583:     ctx.fillRect(0, 0, w, h);
584:     // wall tiles
585:     ctx.strokeStyle = 'rgba(142,182,182,.045)';
586:     ctx.lineWidth = 1;
587:     const tile = Math.max(34, w * 0.035);
588:     for (let x = 0; x < w; x += tile) {
589:       ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
590:     }
591:     for (let y = 0; y < h; y += tile) {
592:       ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
593:     }
594:     // warm spotlights
595:     for (const [cx, cy, r] of [[w * 0.36, 0, w * 0.42], [w * 0.72, 0, w * 0.34], [w * 0.1, 0, w * 0.25]]) {
596:       const g = ctx.createRadialGradient(cx, cy, 5, cx, cy, r);
597:       g.addColorStop(0, 'rgba(255,207,130,.13)');
598:       g.addColorStop(0.45, 'rgba(255,183,96,.04)');
599:       g.addColorStop(1, 'rgba(255,183,96,0)');
600:       ctx.fillStyle = g;
601:       ctx.fillRect(cx - r, 0, r * 2, r * 1.3);
602:     }
603:     // wall panelling
604:     ctx.fillStyle = 'rgba(8,17,20,.45)';
605:     for (let i = 0; i < 4; i++) {
606:       const x = w * (0.06 + i * 0.25);
607:       ctx.fillRect(x, h * 0.11, 1, h * 0.75);
608:     }
609:     // rack labels
610:     const labelY = top - 13;
611:     ctx.textAlign = 'left';
612:     ctx.textBaseline = 'middle';
613:     ctx.font = `700 ${Math.max(7, Math.min(10, w * 0.007))}px "Courier New", monospace`;
614:     ctx.fillStyle = 'rgba(231,197,119,.66)';
615:     ctx.fillText('P R E D A T O R   R A C K', left, labelY);
616:     ctx.fillStyle = 'rgba(143,164,167,.55)';
617:     ctx.textAlign = 'right';
618:     ctx.fillText('2 × 200 CM', left + availW, labelY);
619:     if (!layout.portrait) {
620:       const sy = layout.sy;
621:       ctx.textAlign = 'left';
622:       ctx.fillStyle = 'rgba(231,197,119,.55)';
623:       ctx.fillText('N A N O   R A C K', left, sy - 12);
624:       ctx.fillStyle = 'rgba(143,164,167,.45)';
625:       ctx.textAlign = 'right';
626:       ctx.fillText('5 × 50 CM', left + availW, sy - 12);
627:     }
628:     // floor
629:     const floorY = h * 0.79;
630:     const fg = ctx.createLinearGradient(0, floorY, 0, h);
631:     fg.addColorStop(0, 'rgba(12,24,26,0)');
632:     fg.addColorStop(0.35, 'rgba(10,18,19,.55)');
633:     fg.addColorStop(1, 'rgba(5,10,11,.95)');
634:     ctx.fillStyle = fg;
635:     ctx.fillRect(0, floorY, w, h - floorY);
636:     // floor plank lines
637:     ctx.strokeStyle = 'rgba(155,132,92,.07)';
638:     for (let i = 0; i < 6; i++) {
639:       ctx.beginPath();
640:       ctx.moveTo(0, floorY + 30 + i * 34);
641:       ctx.lineTo(w, floorY + 20 + i * 34);
642:       ctx.stroke();
643:     }
644:     // hanging light glow dots
645:     ctx.fillStyle = 'rgba(255,224,166,.8)';
646:     for (const x of [w * 0.3, w * 0.63]) {
647:       ctx.fillRect(x - 3, 18, 6, 2);
648:       ctx.fillStyle = 'rgba(255,188,108,.05)';
649:       ctx.fillRect(x - 20, 20, 40, 4);
650:       ctx.fillStyle = 'rgba(255,224,166,.8)';
651:     }
652:   }
653: 
654:   drawRacks(ctx, layout, time) {
655:     const { left, top, availW, bigH, bigGap, portrait } = layout;
656:     if (portrait) return;
657:     const x0 = left - 14;
658:     const x1 = left + availW + 10;
659:     const y0 = top - 8;
660:     const y1 = top + bigH + 15;
661:     // metal posts
662:     ctx.fillStyle = '#1b252a';
663:     ctx.fillRect(x0, y0, 6, y1 - y0);
664:     ctx.fillRect(x1 - 2, y0, 6, y1 - y0);
665:     ctx.fillRect(x0, y0, x1 - x0, 4);
666:     ctx.fillRect(x0, y1 - 4, x1 - x0, 4);
667:     ctx.fillStyle = 'rgba(154,181,183,.16)';
668:     ctx.fillRect(x0 + 1, y0, 1, y1 - y0);
669:     ctx.fillRect(x0, y0 + 1, x1 - x0, 1);
670:     // bolts
671:     ctx.fillStyle = '#657277';
672:     for (const bx of [x0 + 3, x1 + 1]) {
673:       for (const by of [y0 + 8, y0 + bigH * 0.55, y1 - 8]) {
674:         ctx.beginPath(); ctx.arc(bx, by, 1.5, 0, TAU); ctx.fill();
675:       }
676:     }
677:   }
678: 
679:   drawStand(ctx, region, tank, layout, time) {
680:     const { portrait } = layout;
681:     if (portrait) return;
682:     const y = region.y + region.h + 3;
683:     const shelf = ctx.createLinearGradient(0, y, 0, y + 13);
684:     shelf.addColorStop(0, '#5b4229');
685:     shelf.addColorStop(0.2, '#3c2b1c');
686:     shelf.addColorStop(1, '#1d140d');
687:     ctx.fillStyle = shelf;
688:     ctx.fillRect(region.x - 2, y, region.w + 4, 10);
689:     ctx.fillStyle = 'rgba(255,220,160,.1)';
690:     ctx.fillRect(region.x - 2, y, region.w + 4, 1);
691:     // drawer face
692:     if (!portrait) {
693:       const dy = y + 10;
694:       const dh = Math.max(14, layout.h * 0.026);
695:       ctx.fillStyle = '#2c2016';
696:       ctx.fillRect(region.x + 3, dy, region.w - 6, dh);
697:       ctx.strokeStyle = 'rgba(224,191,132,.12)';
698:       ctx.strokeRect(region.x + 3.5, dy + 0.5, region.w - 7, dh - 1);
699:       ctx.fillStyle = '#b4935b';
700:       ctx.fillRect(region.x + region.w / 2 - 14, dy + dh / 2, 28, 3);
701:     }
702:   }
703: 
704:   drawTankAura(ctx, region, compatible, time) {
705:     const pulse = 0.5 + Math.sin(time * 2.4) * 0.18;
706:     ctx.save();
