200:   // -------------------------------------------------------------------- audio
201:   ensureAudio() {
202:     if (this.audio) return;
203:     try {
204:       const Ctx = window.AudioContext || window.webkitAudioContext;
205:       if (Ctx) this.audio = new Ctx();
206:     } catch (e) { /* audio unavailable */ }
207:   }
