209:   tone(freq, dur, type = 'sine', vol = 0.035, delay = 0, slide = 0) {
210:     if (!this.state.sound) return;
211:     this.ensureAudio();
212:     if (!this.audio) return;
213:     if (this.audio.state === 'suspended') this.audio.resume();
214:     const t0 = this.audio.currentTime + delay;
215:     const osc = this.audio.createOscillator();
216:     const g = this.audio.createGain();
217:     osc.type = type;
218:     osc.frequency.setValueAtTime(freq, t0);
219:     if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(40, freq + slide), t0 + dur);
220:     g.gain.setValueAtTime(0.0001, t0);
221:     g.gain.exponentialRampToValueAtTime(vol, t0 + 0.012);
222:     g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
223:     osc.connect(g);
224:     g.connect(this.audio.destination);
225:     osc.start(t0);
226:     osc.stop(t0 + dur + 0.02);
227:   }
