229:   sfx(kind) {
230:     if (!this.state.sound) return;
231:     switch (kind) {
232:       case 'coin': this.tone(920, 0.08, 'sine', 0.03); this.tone(1380, 0.12, 'sine', 0.025, 0.06); break;
233:       case 'feed': this.tone(380, 0.08, 'triangle', 0.028); this.tone(520, 0.1, 'triangle', 0.02, 0.06); break;
234:       case 'buy': this.tone(440, 0.07, 'triangle', 0.025); this.tone(660, 0.08, 'triangle', 0.02, 0.06); this.tone(880, 0.12, 'triangle', 0.016, 0.12); break;
235:       case 'place': this.tone(300, 0.08, 'sine', 0.03); this.tone(480, 0.12, 'sine', 0.02, 0.05); break;
236:       case 'clean': this.tone(240, 0.07, 'sawtooth', 0.012); this.tone(360, 0.1, 'sine', 0.02, 0.05); break;
237:       case 'error': this.tone(150, 0.14, 'square', 0.018, 0, -30); break;
238:       default: this.tone(360, 0.045, 'sine', 0.016);
239:     }
240:   }
