575:   pairState(tank) {
576:     const fishes = this.selectedFish.map(id => tank.fish.find(f => f.id === id)).filter(Boolean);
577:     if (fishes.length < 2) return { ok: false, reason: 'Select two adult fish — one male, one female.' };
578:     const [a, b] = fishes;
579:     if (a.id === b.id) return { ok: false, reason: 'Choose two different fish.' };
580:     if (a.speciesId !== b.speciesId) return { ok: false, reason: 'Both parents must be the same species.' };
581:     if (a.sex === b.sex) return { ok: false, reason: 'You need one male and one female.' };
582:     if (a.growth < 0.95 || b.growth < 0.95) return { ok: false, reason: 'Both fish must be fully grown.' };
583:     if (a.fullness < 55 || b.fullness < 55) return { ok: false, reason: 'Feed both fish to at least 55% fullness.' };
584:     if (tank.cleanliness < 55) return { ok: false, reason: 'Water is too dirty to spawn. Clean the tank.' };
585:     if (a.cooldown > 0 || b.cooldown > 0) return { ok: false, reason: 'This pair needs more rest before spawning again.' };
586:     if (tank.eggs.length) return { ok: false, reason: 'A clutch is already incubating here.' };
587:     if (this.state.money < 50000) return { ok: false, reason: 'Need 50.000 VNĐ for the breeding fee.' };
588:     return { ok: true, reason: 'Ready — a clutch will hatch in about 38 seconds.' };
589:   }
