591:   refreshDetailDynamic() {
592:     if (!this.detailOpen) return;
593:     const tank = tankById(this.state, this.detailTankId);
594:     if (!tank) return;
595:     const clarity = Math.round(tank.cleanliness);
596:     const ph = (tank.ph - (100 - tank.cleanliness) / 100 * 0.35).toFixed(2);
597:     $('stageTemp').textContent = `${tank.temp.toFixed(1)}°C`;
598:     $('stageCap').textContent = `${tank.fish.length} / ${tank.capacity}`;
599:     const clarityLabel = $('clarityLabel');
600:     if (clarityLabel) clarityLabel.textContent = `${clarity}% ${clarity > 65 ? 'CLEAR' : clarity > 35 ? 'CLOUDY' : 'DIRTY'}`;
601:     const set = (id, v) => { const el = $(id); if (el) el.textContent = v; };
602:     set('wClarityVal', `${clarity}%`);
603:     set('wTempVal', `${tank.temp.toFixed(1)}°C`);
604:     set('wPhVal', ph);
605:     set('wO2Val', `${Math.round(tank.oxygen)}%`);
606:     const cb = $('wClarityBar');
607:     if (cb) {
608:       cb.style.width = `${clarity}%`;
609:       const bar = cb.parentElement;
610:       bar.classList.toggle('warn', clarity <= 65 && clarity > 35);
611:       bar.classList.toggle('bad', clarity <= 35);
612:     }
613:     const ob = $('wO2Bar');
614:     if (ob) ob.style.width = `${Math.round(tank.oxygen)}%`;
615:     // fullness bars
616:     document.querySelectorAll('[data-full]').forEach(el => {
617:       const fish = tank.fish.find(f => f.id === el.dataset.full);
618:       if (fish) el.style.width = `${Math.round(fish.fullness)}%`;
619:     });
620:     // cleaning hud
621:     const cleanBar = $('cleanBar');
622:     if (cleanBar) cleanBar.style.backgroundSize = `${clarity}% 100%`;
623:     const cleanPct = $('cleanPct');
624:     if (cleanPct) cleanPct.textContent = `${clarity}%`;
625:     // inspect hud
626:     set('inspectTemp', `${tank.temp.toFixed(1)}°C`);
627:     set('inspectPh', ph);
628:     set('inspectO2', `${Math.round(tank.oxygen)}%`);
629:     set('inspectClarity', `${clarity}%`);
630:     // eggs
