934:   onSceneClick(e) {
935:     if (this.suppressClick) return;
936:     const p = this.localPoint(this.sceneCanvas, e);
937:     const drop = this.renderer.dropAt(p.x, p.y);
938:     if (drop) {
939:       this.collect(drop, e.clientX, e.clientY);
940:       return;
941:     }
942:     const hit = this.renderer.tankAt(p.x, p.y);
943:     if (!hit) {
944:       if (this.selectedTray) {
945:         this.selectedTray = null;
946:         this.syncRendererSelection();
947:         this.renderTray();
948:       }
949:       return;
950:     }
951:     if (this.selectedTray) {
952:       const item = this.state.tray.find(i => i.uid === this.selectedTray);
953:       if (!item) { this.selectedTray = null; return; }
954:       if (item.kind === 'fish') {
955:         const res = placeTrayFish(this.state, item.uid, hit.id);
956:         if (res.ok) {
957:           this.selectedTray = null;
958:           this.handleResult(res, 'place');
959:         } else {
960:           this.handleResult(res);
961:         }
962:       } else {
963:         const water = hit.water;
964:         const nx = clamp((p.x - water.x) / water.w, 0.1, 0.9);
965:         const ny = clamp((p.y - water.y) / water.h, 0.82, 0.97);
966:         this.openTank(hit.id, { decorTrayUid: item.uid, nx, ny });
967:       }
968:       return;
969:     }
970:     this.openTank(hit.id);
971:   }
