function drawHump(ctx, species) {
  if (species.body !== 'round') return;
  const c = species.colors;
  const p = BODY.round;
  const x0 = p.x1 - 38;
  for (let x = x0; x <= p.x1 - 1; x++) {
    const t = (x - x0) / 37;
    const h = Math.pow(Math.sin(t * Math.PI * 0.94), 0.68) * 20;
    for (let y = Math.round(CY - 14 - h); y < Math.round(CY - 10); y++) {
      const v = (y - (CY - 14 - h)) / Math.max(1, h + 4);
      let col = mix(c.back, c.base, 0.16 + v * 0.68);
      if (v < 0.2) col = mix(col, c.fin2, 0.22);
      if (v > 0.8) col = mix(col, c.belly, 0.24);
      ctx.fillStyle = col;
      ctx.fillRect(x, y, 1, 1);
    }
  }
  // glossy crown highlight
  ctx.fillStyle = alpha(c.fin2, 0.5);
  ctx.fillRect(p.x1 - 29, CY - 31, 9, 2);
  ctx.fillRect(p.x1 - 26, CY - 29, 4, 1);
  ctx.fillStyle = alpha('#ffffff', 0.18);
  ctx.fillRect(p.x1 - 32, CY - 28, 3, 1);
  // faint red bloom on the hump
  ctx.fillStyle = alpha(c.red || c.fin, 0.35);
  for (let i = 0; i < 9; i++) {
    const hx = p.x1 - 31 + (i * 13) % 24;
    const hy = CY - 31 + (i * 7) % 16;
    ctx.fillRect(hx, hy, 1 + (i % 2), 1);
  }
  ctx.fillStyle = alpha(c.accent, 0.35);
  ctx.fillRect(x0, CY - 15, 3, 1);
}

