import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, executablePath: join(process.env.HOME, '.cache/ms-playwright/chromium-1248/chrome-linux64/chrome') });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const errors = [];
const warnings = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.addInitScript(() => localStorage.clear());
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(600);

const state = () => page.evaluate(() => window.__THUYCUNG__.state);
const money = async () => (await state()).money;
const toast = () => page.locator('.toast').last().innerText().catch(() => '');
const checks = [];
function check(name, ok, detail = '') {
  checks.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'} · ${name}${detail ? ' — ' + detail : ''}`);
}

// 1. Predator refuses pellets; accepts bloodworms.
await page.evaluate(() => window.__THUYCUNG__.ui.openTank('P1'));
await page.waitForTimeout(350);
let before = await state();
await page.locator('.food-quick [data-food="pellets"]').click();
await page.locator('[data-action="feed"]').click();
await page.waitForTimeout(120);
let after = await state();
check('predator refuses pellets', after.foods.pellets === before.foods.pellets && /refuse pellets/i.test(await toast()), await toast());
await page.locator('.food-quick [data-food="bloodworms"]').click();
before = await state();
await page.locator('[data-action="feed"]').click();
await page.waitForTimeout(160);
after = await state();
check('predator accepts bloodworms', after.foods.bloodworms === before.foods.bloodworms - 1, `${before.foods.bloodworms}->${after.foods.bloodworms}`);
const fedFullness = after.tanks.find(t => t.id === 'P1').fish[0].fullness;
check('feeding raises fullness', fedFullness > 70, `fullness ${fedFullness.toFixed(1)}`);

// 2. Clean via scrub.
const cleanBefore = (await state()).tanks.find(t => t.id === 'P1').cleanliness;
await page.locator('[data-action="clean"]').click();
await page.waitForTimeout(120);
const box = await page.locator('#detailCanvas').boundingBox();
const water = await page.evaluate(() => window.__THUYCUNG__.ui.detailView.hit.water);
for (let i = 0; i <= 26; i++) {
  const x = water.x + water.w * (0.16 + (i % 13) / 15);
  const y = water.y + water.h * (0.22 + (Math.floor(i / 13) % 2) * 0.42);
  await page.mouse.move(box.x + x, box.y + y);
  if (i === 0) await page.mouse.down();
  await page.waitForTimeout(45);
}
await page.mouse.up();
const cleanAfter = (await state()).tanks.find(t => t.id === 'P1').cleanliness;
check('scrub cleans glass', cleanAfter > cleanBefore + 20, `${cleanBefore.toFixed(1)}->${cleanAfter.toFixed(1)}`);
await page.screenshot({ path: 'screenshots/test-clean.png' });
await page.locator('#cleanDone').click();

// 3. Inspect lens.
await page.locator('[data-action="inspect"]').click();
const lensPoint = await page.evaluate(() => {
  const v = window.__THUYCUNG__.ui.detailView.hit.water;
  return { x: v.x + v.w * 0.55, y: v.y + v.h * 0.45 };
});
await page.mouse.move(box.x + lensPoint.x, box.y + lensPoint.y);
await page.waitForTimeout(300);
const lens = await page.evaluate(() => window.__THUYCUNG__.ui.detailView.lens);
check('inspection lens visible', !!lens, lens ? `r=${lens.r.toFixed(0)}` : 'no lens');
await page.screenshot({ path: 'screenshots/test-inspect.png' });
await page.locator('[data-action="inspect"]').click();
await page.evaluate(() => window.__THUYCUNG__.ui.closeDetail());

// 4. Shop buys fish, food, decor.
await page.locator('#shopBtn').click();
await page.waitForTimeout(200);
let m0 = await money();
await page.locator('[data-buy-fish="paradise"]').click();
await page.waitForTimeout(120);
let s1 = await state();
check('buy fish adds to tray', s1.tray.some(i => i.speciesId === 'paradise') && s1.money === m0 - 68000, `money ${s1.money}`);
await page.locator('#shopTabs [data-tab="food"]').click();
const pellets0 = s1.foods.pellets;
await page.locator('[data-buy-food="pellets"]').click();
await page.waitForTimeout(120);
let s2 = await state();
check('buy food restocks uses', s2.foods.pellets === pellets0 + 25, `${pellets0}->${s2.foods.pellets}`);
await page.locator('#shopTabs [data-tab="decor"]').click();
await page.locator('[data-buy-decor="driftwood"]').click();
await page.waitForTimeout(120);
let s3 = await state();
check('buy decor adds to tray', s3.tray.some(i => i.decorType === 'driftwood'), `tray ${s3.tray.length}`);
await page.screenshot({ path: 'screenshots/test-shop.png' });
await page.locator('#shopModal [data-close="shop"]').last().click();

// 5. Place fish from tray into an empty nano tank by clicking it.
const fishUid = (await state()).tray.find(i => i.speciesId === 'paradise').uid;
await page.locator(`.tray-slot[data-uid="${fishUid}"]`).click();
const tankPoint = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S5');
  return { x: h.region.x + h.region.w / 2, y: h.region.y + h.region.h / 2 };
});
await page.mouse.click(tankPoint.x, tankPoint.y);
await page.waitForTimeout(250);
let s4 = await state();
check('place fish from tray', s4.tanks.find(t => t.id === 'S5').fish.length === 1 && !s4.tray.some(i => i.uid === fishUid), `S5 ${s4.tanks.find(t => t.id === 'S5').fish.length}`);

// 6. Place decor from tray, drag ghost, confirm.
const decorUid = (await state()).tray.find(i => i.decorType === 'driftwood').uid;
await page.locator(`.tray-slot[data-uid="${decorUid}"]`).click();
const s1Point = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S1');
  return { x: h.region.x + h.region.w * 0.48, y: h.region.y + h.region.h * 0.55 };
});
await page.mouse.click(s1Point.x, s1Point.y);
await page.waitForTimeout(500);
const detailOpen = await page.evaluate(() => window.__THUYCUNG__.ui.detailOpen && window.__THUYCUNG__.ui.detailMode);
check('decor opens placement mode', detailOpen === 'decor', String(detailOpen));
const decorBefore = (await state()).tanks.find(t => t.id === 'S1').decor.length;
const dbox = await page.locator('#detailCanvas').boundingBox();
const dwater = await page.evaluate(() => window.__THUYCUNG__.ui.detailView.hit.water);
await page.mouse.move(dbox.x + dwater.x + dwater.w * 0.52, dbox.y + dwater.y + dwater.h * 0.9);
await page.waitForTimeout(180);
await page.locator('#decorConfirm').click();
await page.waitForTimeout(220);
let s5 = await state();
check('confirm decor placement', s5.tanks.find(t => t.id === 'S1').decor.length === decorBefore + 1 && !s5.tray.some(i => i.uid === decorUid), `decor ${s5.tanks.find(t => t.id === 'S1').decor.length}, tray ${s5.tray.length}`);
await page.screenshot({ path: 'screenshots/test-decor.png' });
await page.evaluate(() => window.__THUYCUNG__.ui.closeDetail());

// 7. Drag a fish from the tray straight onto a tank.
await page.locator('#shopBtn').click();
await page.locator('[data-buy-fish="betta_crown"]').click();
await page.waitForTimeout(120);
await page.locator('#shopModal [data-close="shop"]').last().click();
const dragUid = (await state()).tray.find(i => i.speciesId === 'betta_crown').uid;
const slotBox = await page.locator(`.tray-slot[data-uid="${dragUid}"]`).boundingBox();
const s4Point = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S4');
  return { x: h.region.x + h.region.w / 2, y: h.region.y + h.region.h / 2 };
});
await page.mouse.move(slotBox.x + slotBox.width / 2, slotBox.y + slotBox.height / 2);
await page.mouse.down();
await page.mouse.move(slotBox.x + slotBox.width / 2 + 30, slotBox.y - 40, { steps: 6 });
await page.mouse.move(s4Point.x, s4Point.y, { steps: 14 });
await page.mouse.up();
await page.waitForTimeout(320);
let s6 = await state();
check('drag fish from tray onto tank', s6.tanks.find(t => t.id === 'S4').fish.length === 2 && !s6.tray.some(i => i.uid === dragUid), `S4 ${s6.tanks.find(t => t.id === 'S4').fish.length}`);

// 8. Breed two paradise fish in S2 then hatch.
await page.evaluate(() => window.__THUYCUNG__.ui.openTank('S2'));
await page.waitForTimeout(350);
const cards = page.locator('[data-fish]');
await cards.nth(0).click();
await page.locator('[data-fish]').nth(1).click();
await page.waitForTimeout(180);
let pairOk = await page.locator('#breedBtn').isEnabled();
check('valid pair enables breeding', pairOk);
const moneyB = await money();
await page.locator('#breedBtn').click();
await page.waitForTimeout(200);
let s7 = await state();
check('breeding creates clutch and charges fee', s7.tanks.find(t => t.id === 'S2').eggs.length === 1 && s7.money === moneyB - 50000, `eggs ${s7.tanks.find(t => t.id === 'S2').eggs.length}, money ${s7.money}`);
await page.screenshot({ path: 'screenshots/test-breed.png' });
const fishBeforeHatch = s7.tanks.find(t => t.id === 'S2').fish.length;
await page.evaluate(() => {
  const t = window.__THUYCUNG__.state.tanks.find(t => t.id === 'S2');
  if (t.eggs[0]) t.eggs[0].timer = 0.05;
});
await page.waitForTimeout(900);
let s8 = await state();
check('eggs hatch into fry', s8.tanks.find(t => t.id === 'S2').fish.length >= fishBeforeHatch + 2 && s8.tanks.find(t => t.id === 'S2').eggs.length === 0, `fish ${s8.tanks.find(t => t.id === 'S2').fish.length}`);
await page.evaluate(() => window.__THUYCUNG__.ui.closeDetail());

// 9. Collect a money drop from the room.
const dropInfo = await page.evaluate(() => {
  const d = window.__THUYCUNG__.renderer.hit.drops[0];
  return d ? { id: d.id, x: d.x, y: d.y, value: d.value } : null;
});
if (dropInfo) {
  const mBefore = await money();
  await page.mouse.click(dropInfo.x, dropInfo.y);
  await page.waitForTimeout(180);
  const mAfter = await money();
  check('collect banknote', mAfter === mBefore + dropInfo.value, `+${dropInfo.value}`);
} else {
  check('collect banknote', false, 'no drop on screen');
}

// 10. Help modal and escape.
await page.locator('#helpBtn').click();
await page.waitForTimeout(160);
check('help modal opens', await page.locator('#helpModal').isVisible());
await page.keyboard.press('Escape');
await page.waitForTimeout(150);
check('escape closes help', await page.locator('#helpModal').isHidden());

// 11. Invalid placement: predator into nano.
await page.locator('#shopBtn').click();
await page.locator('[data-buy-fish="gar"]').click();
await page.waitForTimeout(120);
await page.locator('#shopModal [data-close="shop"]').last().click();
const garUid = (await state()).tray.find(i => i.speciesId === 'gar').uid;
await page.locator(`.tray-slot[data-uid="${garUid}"]`).click();
const s5Point = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S5');
  return { x: h.region.x + h.region.w / 2, y: h.region.y + h.region.h / 2 };
});
await page.mouse.click(s5Point.x, s5Point.y);
await page.waitForTimeout(220);
let s9 = await state();
check('predator cannot go in nano tank', s9.tray.some(i => i.uid === garUid) && s9.tanks.find(t => t.id === 'S5').fish.length === 1, await toast());

// 12. Selling a fish.
await page.evaluate(() => window.__THUYCUNG__.ui.openTank('S4'));
await page.waitForTimeout(350);
const sellCount = (await state()).tanks.find(t => t.id === 'S4').fish.length;
const moneyS = await money();
await page.locator('[data-sell]').first().click();
await page.waitForTimeout(200);
let s10 = await state();
check('sell fish works', s10.tanks.find(t => t.id === 'S4').fish.length === sellCount - 1 && s10.money > moneyS, `S4 ${s10.tanks.find(t => t.id === 'S4').fish.length}`);
await page.evaluate(() => window.__THUYCUNG__.ui.closeDetail());

console.log('\nSUMMARY', checks.filter(c => !c.ok).length === 0 ? 'ALL PASS' : `${checks.filter(c => !c.ok).length} FAIL`);
console.log('PAGE ERRORS', errors);
await browser.close();

