import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true, executablePath: join(process.env.HOME, '.cache/ms-playwright/chromium-1248/chrome-linux64/chrome') });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.addInitScript(() => localStorage.clear());
await page.goto('http://localhost:3002', { waitUntil: 'networkidle' });
await page.waitForTimeout(700);

const checks = [];
function check(name, ok, detail = '') {
  checks.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'} · ${name}${detail ? ' — ' + detail : ''}`);
}
const state = () => page.evaluate(() => window.__THUYCUNG__.state);

const overflow = await page.evaluate(() => ({
  sw: document.documentElement.scrollWidth, iw: window.innerWidth,
  brand: document.querySelector('.brand-text h1').getBoundingClientRect().toJSON(),
  wallet: document.querySelector('.wallet').getBoundingClientRect().toJSON(),
  actions: document.querySelector('.top-actions').getBoundingClientRect().toJSON()
}));
check('no horizontal overflow', overflow.sw <= overflow.iw + 1, `${overflow.sw} <= ${overflow.iw}`);
check('brand title stays one line', overflow.brand.height < 20, `height ${overflow.brand.height.toFixed(1)}`);
check('wallet inside viewport', overflow.wallet.right <= overflow.iw, `right ${overflow.wallet.right}`);
await page.screenshot({ path: 'screenshots/mobile.png' });

// Open a tank by tapping it.
const s1 = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S1');
  return { x: h.region.x + h.region.w / 2, y: h.region.y + h.region.h / 2 };
});
await page.touchscreen.tap(s1.x, s1.y);
await page.waitForTimeout(450);
check('tap opens tank detail', await page.evaluate(() => window.__THUYCUNG__.ui.detailOpen));
await page.screenshot({ path: 'screenshots/mobile-detail.png' });

// Feed nano fish with pellets via quick food + tap.
const before = await state();
await page.locator('.food-quick [data-food="pellets"]').tap();
await page.locator('[data-action="feed"]').tap();
await page.waitForTimeout(220);
const after = await state();
check('mobile feed works', after.foods.pellets === before.foods.pellets - 1, `${before.foods.pellets}->${after.foods.pellets}`);

// Scrub with a touch drag across the glass.
await page.locator('[data-action="clean"]').tap();
await page.waitForTimeout(150);
const box = await page.locator('#detailCanvas').boundingBox();
const water = await page.evaluate(() => window.__THUYCUNG__.ui.detailView.hit.water);
const cleanBefore = (await state()).tanks.find(t => t.id === 'S1').cleanliness;
await page.mouse.move(box.x + water.x + water.w * 0.2, box.y + water.y + water.h * 0.35);
await page.mouse.down();
for (let i = 0; i < 12; i++) {
  await page.mouse.move(box.x + water.x + water.w * (0.2 + i * 0.055), box.y + water.y + water.h * (0.35 + (i % 2) * 0.25));
  await page.waitForTimeout(45);
}
await page.mouse.up();
const cleanAfter = (await state()).tanks.find(t => t.id === 'S1').cleanliness;
check('mobile scrub cleans glass', cleanAfter > cleanBefore + 5, `${cleanBefore.toFixed(1)}->${cleanAfter.toFixed(1)}`);
await page.locator('#cleanDone').tap();
await page.locator('#detailModal [data-close="detail"]').last().tap();
await page.waitForTimeout(200);

// Shop and decor placement on mobile.
await page.locator('#shopBtn').tap();
await page.waitForTimeout(250);
await page.screenshot({ path: 'screenshots/mobile-shop.png' });
check('mobile shop opens', await page.locator('#shopModal').isVisible());
await page.locator('#shopTabs [data-tab="decor"]').tap();
await page.locator('[data-buy-decor="lotus"]').tap();
await page.waitForTimeout(160);
const trayUid = (await state()).tray.find(i => i.decorType === 'lotus')?.uid;
check('mobile decor purchase', !!trayUid);
await page.locator('#shopModal [data-close="shop"]').last().tap();
await page.waitForTimeout(220);
await page.locator(`.tray-slot[data-uid="${trayUid}"]`).tap();
await page.waitForTimeout(150);
const s2 = await page.evaluate(() => {
  const h = window.__THUYCUNG__.renderer.hit.tanks.find(t => t.id === 'S2');
  return { x: h.region.x + h.region.w * 0.5, y: h.region.y + h.region.h * 0.5 };
});
await page.touchscreen.tap(s2.x, s2.y);
await page.waitForTimeout(500);
check('mobile decor placement mode', await page.evaluate(() => window.__THUYCUNG__.ui.detailMode === 'decor'));
const db = await page.locator('#detailCanvas').boundingBox();
const dw = await page.evaluate(() => window.__THUYCUNG__.ui.detailView.hit.water);
await page.mouse.move(db.x + dw.x + dw.w * 0.6, db.y + dw.y + dw.h * 0.9);
await page.waitForTimeout(180);
await page.locator('#decorConfirm').tap();
await page.waitForTimeout(220);
const s2decor = (await state()).tanks.find(t => t.id === 'S2').decor.length;
check('mobile decor confirmed', s2decor === 3, `S2 decor ${s2decor}`);
await page.screenshot({ path: 'screenshots/mobile-decor.png' });
await page.locator('#detailModal [data-close="detail"]').last().tap();

// Small-phone pass (360 wide): no overflow, day chip may hide.
await page.setViewportSize({ width: 360, height: 780 });
await page.waitForTimeout(400);
const small = await page.evaluate(() => ({
  sw: document.documentElement.scrollWidth, iw: window.innerWidth,
  dayHidden: getComputedStyle(document.querySelector('.day-chip')).display === 'none',
  brand: document.querySelector('.brand-text h1').getBoundingClientRect().toJSON()
}));
check('small phone no overflow', small.sw <= small.iw + 1, `${small.sw} <= ${small.iw}`);
check('small phone title one line', small.brand.height < 20, `height ${small.brand.height.toFixed(1)}`);
console.log('day chip hidden at 360:', small.dayHidden);
await page.screenshot({ path: 'screenshots/mobile-360.png' });

console.log('\nSUMMARY', checks.filter(c => !c.ok).length === 0 ? 'ALL PASS' : `${checks.filter(c => !c.ok).length} FAIL`);
console.log('PAGE ERRORS', errors);
await browser.close();

